  NULL,
  $$Individual$$,
  $$demo-abdiwali-hersi-warsame$$,
  $$Abdiwali Hersi Warsame$$,
  $$Nutrition Survey Specialist | SMART Surveys & Humanitarian Nutrition | Somali Region & Somalia$$,
  $$Hargeisa, Somalia$$,
