  $$[{"id":"e30e954b-e6e7-441c-8a4f-423bab299702","role":"Nutrition Surveillance Coordinator","end_year":2025,"logo_url":null,"start_year":2020,"description":"Coordinated nutrition surveillance and SMART surveys across Somaliland and Puntland.","organization":"Save the Children Somalia"},{"id":"1b267040-2a9c-451c-ad58-17f5f8f459c6","role":"Nutrition Analyst","end_year":2020,"logo_url":null,"start_year":2017,"description":"Analysed seasonal nutrition assessments for the Food Security and Nutrition Analysis Unit.","organization":"FAO Somalia (FSNAU)"}]$$::jsonb,
  $$[{"id":"3ecb2400-1e2a-47fd-b762-6cca612e8761","end_year":2015,"logo_url":null,"start_year":2011,"institution":"University of Hargeisa","degree_or_course":"BSc Public Health"},{"id":"46bb26c3-27d8-4eb9-b88c-2424c7ef35a9","end_year":2020,"logo_url":null,"start_year":2018,"institution":"Jigjiga University","degree_or_course":"MPH (Nutrition)"}]$$::jsonb,
