INSERT INTO portfolio_items (id, profile_id, project_name, organization, organization_id, start_year, end_year, role, description, results, images, links, video_url, sort_order) VALUES
  ('30329ba5-e8e1-43a6-b4bc-41765bdd0eb7', '340f760f-5bd6-5468-b5dc-61786475bc03', $$Impact Evaluation of a Pan-African Scholarship Programme$$, $$Mastercard Foundation$$, (SELECT id FROM organizations WHERE name = $$Mastercard Foundation$$), 2018, 2023, $$Evaluation Lead$$, $$Longitudinal impact evaluation of scholars' education, employment and leadership outcomes.$$, $$Evaluation shaped the programme's next ten-year strategy.$$, $$[{"url":"https://picsum.photos/seed/demo-margaret-ellison-shaw-portfolio-1/600/400","caption":null},{"url":"https://picsum.photos/seed/demo-margaret-ellison-shaw-portfolio-1-img1/900/600","caption":"Scholar interviews in Accra"}]$$::jsonb, $$[]$$::jsonb, NULL, 1),
  ('b26ef462-e07e-443b-b84c-efaa89e81c3a', '340f760f-5bd6-5468-b5dc-61786475bc03', $$Quality Assurance Reform Advice, Tunisia$$, $$World Bank$$, (SELECT id FROM organizations WHERE name = $$World Bank$$), 2016, 2017, $$Tertiary Education Expert$$, $$Advised on accreditation and quality assurance for public universities.$$, $$New accreditation agency established.$$, $$[{"url":"https://picsum.photos/seed/demo-margaret-ellison-shaw-portfolio-2/600/400","caption":null},{"url":"https://picsum.photos/seed/demo-margaret-ellison-shaw-portfolio-2-img1/900/600","caption":"Workshop at a Tunis university"}]$$::jsonb, $$[]$$::jsonb, NULL, 2),
  ('9c5273d9-f825-5d2c-b8e3-2a0b0e73c2a5', '340f760f-5bd6-5468-b5dc-61786475bc03', $$Graduate Tracer Study Method for African Universities$$, $$Mastercard Foundation$$, (SELECT id FROM organizations WHERE name = $$Mastercard Foundation$$), 2022, 2023, $$Lead Evaluator$$, $$Designed a common graduate tracer study method for eight partner universities, including the questionnaire, sampling and a shared data platform, and trained university staff to run it.$$, $$Eight universities ran the first round; response rates averaged 64%.$$, $$[{"url":"https://picsum.photos/seed/demo-margaret-ellison-shaw-graduate-tracer-study-method-for-african-1/900/600","caption":"Tracer study training in Accra"}]$$::jsonb, $$[]$$::jsonb, NULL, 3),
  ('189b2ffc-0c2c-5b6d-a1fe-34630e27141f', '340f760f-5bd6-5468-b5dc-61786475bc03', $$Systematic Review on Higher Education and Employability$$, $$3ie$$, (SELECT id FROM organizations WHERE name = $$3ie$$), 2020, 2021, $$Principal Investigator$$, $$Led a systematic review of 62 studies on how higher education interventions affect graduates' employment in low- and middle-income countries.$$, $$Review published with an evidence gap map used by two funders.$$, $$[{"url":"https://picsum.photos/seed/demo-margaret-ellison-shaw-systematic-review-on-higher-education-an-1/900/600","caption":"Evidence gap map"}]$$::jsonb, $$[]$$::jsonb, NULL, 4);
INSERT INTO audio_testimonials (id, profile_id, work_history_entry_id, portfolio_item_id, reference_name, reference_org, reference_title, relationship, referee_email, referee_org_id, period_start, period_end, context, audio_path, transcript, transcript_source, transcript_confirmed_at, duration_seconds, source, submission_token, status, precheck_status, review_flags, opened_at, confirmed_at, details_accepted_at, consent_at, submitted_at, published_at, withdraw_token, created_at) VALUES ('5acbae68-d1fc-5a8a-8cdc-41404f6a47e8', '340f760f-5bd6-5468-b5dc-61786475bc03', $$fe78bbd1-b8ac-4899-9beb-4b4c264c4769$$, NULL, $$Prof. David Kessler$$, $$Boston University$$, $$Dean, School of Education$$, $$supervisor$$, $$dkessler@bu.edu$$, (SELECT id FROM organizations WHERE name = $$Boston University$$), 2002, 2016, $$Education policy and the university's evaluation centre$$, $$demo/testimonial-4.m4a$$, $$[Demo testimonial: fictional referee, synthetic audio] Margaret was a professor in our school and directed our evaluation centre for over a decade. She built a team that did rigorous evaluations of higher education programmes around the world. She is a generous mentor and a careful scholar. I would work with her again on any higher education evaluation.$$, $$auto$$, '2026-03-17T15:44:01.103Z'::timestamptz, 88, $$reference_direct$$, NULL, 'published', 'passed', '[]'::jsonb, '2026-03-15T15:44:01.103Z'::timestamptz, '2026-03-17T15:29:37.103Z'::timestamptz, '2026-03-17T15:36:49.103Z'::timestamptz, '2026-03-17T15:44:01.103Z'::timestamptz, '2026-03-17T15:44:01.103Z'::timestamptz, '2026-03-18T15:44:01.103Z'::timestamptz, $$d32f79471c7a2f03ca3f6161fe2c84fd$$, '2026-03-14T15:44:01.103Z'::timestamptz);
