INSERT INTO video_responses (id, profile_id, kind, question_id, video_url, video_path, transcript, duration_seconds) VALUES
  ('2ed36a03-218f-5453-a8d3-0ef8faea9b64', '340f760f-5bd6-5468-b5dc-61786475bc03', 'question', (SELECT id FROM interview_questions WHERE sort_order = 1 AND active ORDER BY id LIMIT 1), NULL, $$demo/qna-1.mp4$$, $$[Demo answer] I'm proudest of the evaluation of a pan-African scholarship programme. I led it for five years. What changed is that the funder added a transition-to-work component after we showed graduates struggled most in their first year after university.$$, 20),
  ('7d1c58b5-149a-5827-b729-9ed5e146ac2a', '340f760f-5bd6-5468-b5dc-61786475bc03', 'question', (SELECT id FROM interview_questions WHERE sort_order = 2 AND active ORDER BY id LIMIT 1), NULL, $$demo/qna-2.mp4$$, $$[Demo answer] In Tunisia I worked on quality assurance reform in a system I didn't know. I spent time with university staff to understand how decisions were made, and I relied on Tunisian colleagues to read the political context.$$, 20),
  ('8de4b5a8-884d-5049-8879-c9eb9d765895', '340f760f-5bd6-5468-b5dc-61786475bc03', 'question', (SELECT id FROM interview_questions WHERE sort_order = 3 AND active ORDER BY id LIMIT 1), NULL, $$demo/qna-3.mp4$$, $$[Demo answer] When our results showed that one component was not working, I presented the evidence early to the funder, with the reasons and options, so they could adjust during the programme rather than after.$$, 20),
  ('58a77f23-7b78-5748-b562-fdb76e2133e1', '340f760f-5bd6-5468-b5dc-61786475bc03', 'question', (SELECT id FROM interview_questions WHERE sort_order = 4 AND active ORDER BY id LIMIT 1), NULL, $$demo/qna-4.mp4$$, $$[Demo answer] I work in English and French, and I always co-lead with researchers from the universities we evaluate. It improves the questions and the use of the findings.$$, 20),
  ('27f858dd-b66c-5bbb-b595-282527f9e5c5', '340f760f-5bd6-5468-b5dc-61786475bc03', 'question', (SELECT id FROM interview_questions WHERE sort_order = 5 AND active ORDER BY id LIMIT 1), NULL, $$demo/qna-5.mp4$$, $$[Demo answer] I specialise in tracer studies and impact evaluation. Tracer studies are not the right tool when you need to know why graduates succeed; then you need interviews and case studies too.$$, 20);
