INSERT INTO portfolio_items (id, profile_id, project_name, organization, organization_id, start_year, end_year, role, description, results, images, links, video_url, sort_order) VALUES
  ('cd2dea06-c44a-4311-8564-50f8162019a9', '8e3cee7c-7992-5539-8a05-3c342a9820c1', $$Climate-Resilient Irrigation for Altiplano Communities$$, $$Inter-American Development Bank$$, (SELECT id FROM organizations WHERE name = $$Inter-American Development Bank$$), 2019, 2023, $$Programme Manager$$, $$Managed design and construction of 35 small irrigation and water harvesting systems with community water committees.$$, $$Irrigated area expanded by 4,200 hectares; water user organizations manage all systems.$$, $$[{"url":"https://picsum.photos/seed/demo-alvaro-choque-mendoza-portfolio-1/600/400","caption":null},{"url":"https://picsum.photos/seed/demo-alvaro-choque-mendoza-portfolio-1-img1/900/600","caption":"Micro-dam on the Altiplano"},{"url":"https://picsum.photos/seed/demo-alvaro-choque-mendoza-portfolio-1-img2/900/600","caption":"Water committee meeting"}]$$::jsonb, $$[]$$::jsonb, NULL, 1),
  ('a073282f-55df-4bda-96bb-ba0d475eb1a8', '8e3cee7c-7992-5539-8a05-3c342a9820c1', $$Glacier Retreat Adaptation Plan, Cordillera Real$$, $$Swiss Agency for Development and Cooperation$$, (SELECT id FROM organizations WHERE name = $$Swiss Agency for Development and Cooperation$$), 2016, 2017, $$Lead Engineer$$, $$Prepared an adaptation plan for water supply and irrigation in basins fed by retreating glaciers.$$, $$Plan financed in a second phase covering 12 municipalities.$$, $$[{"url":"https://picsum.photos/seed/demo-alvaro-choque-mendoza-portfolio-2/600/400","caption":null},{"url":"https://picsum.photos/seed/demo-alvaro-choque-mendoza-portfolio-2-img1/900/600","caption":"Glacier-fed reservoir"}]$$::jsonb, $$[]$$::jsonb, NULL, 2),
  ('704cc6cc-2f38-55d6-956d-ec77af047d1c', '8e3cee7c-7992-5539-8a05-3c342a9820c1', $$Water User Association Strengthening, Oruro$$, $$Swiss Agency for Development and Cooperation$$, (SELECT id FROM organizations WHERE name = $$Swiss Agency for Development and Cooperation$$), 2018, 2019, $$Irrigation Engineer$$, $$Supported 12 water user associations to set water schedules, maintenance fees and conflict resolution rules for rehabilitated irrigation systems, with training in Aymara and Spanish.$$, $$Maintenance fees collected by 11 of 12 associations two years later.$$, $$[{"url":"https://picsum.photos/seed/demo-alvaro-choque-mendoza-water-user-association-strengthening-oru-1/900/600","caption":"Water user association meeting"},{"url":"https://picsum.photos/seed/demo-alvaro-choque-mendoza-water-user-association-strengthening-oru-2/900/600","caption":"Canal maintenance day"}]$$::jsonb, $$[]$$::jsonb, NULL, 3);
INSERT INTO audio_testimonials (id, profile_id, work_history_entry_id, portfolio_item_id, reference_name, reference_org, reference_title, relationship, referee_email, referee_org_id, period_start, period_end, context, audio_path, transcript, transcript_source, transcript_confirmed_at, duration_seconds, source, submission_token, status, precheck_status, review_flags, opened_at, confirmed_at, details_accepted_at, consent_at, submitted_at, published_at, withdraw_token, created_at) VALUES ('cd696bcc-2ade-5fcb-8553-2896d6b1371b', '8e3cee7c-7992-5539-8a05-3c342a9820c1', $$041828e1-b6dd-4e18-8c7b-46cca51b71c0$$, NULL, $$Ing. Rolando Mamani$$, $$Inter-American Development Bank$$, $$Senior Water and Sanitation Specialist$$, $$supervisor$$, $$rolandom@iadb.org$$, (SELECT id FROM organizations WHERE name = $$Inter-American Development Bank$$), 2009, 2016, $$Regional coordination of the MiRiego irrigation programme$$, $$demo/testimonial-6.m4a$$, $$[Demo testimonial: fictional referee, synthetic audio] I supervised Álvaro when he coordinated the MiRiego irrigation programme in the Altiplano, before I joined the IDB. He combined good engineering with real respect for farmers' own water rules. His systems are still working. I would work with him again on irrigation and climate adaptation projects.$$, $$auto$$, '2026-05-11T15:44:01.103Z'::timestamptz, 110, $$reference_direct$$, NULL, 'published', 'passed', '[]'::jsonb, '2026-05-09T15:44:01.103Z'::timestamptz, '2026-05-11T15:29:37.103Z'::timestamptz, '2026-05-11T15:36:49.103Z'::timestamptz, '2026-05-11T15:44:01.103Z'::timestamptz, '2026-05-11T15:44:01.103Z'::timestamptz, '2026-05-12T15:44:01.103Z'::timestamptz, $$4b50bd46a385f7c0d13901a306041c22$$, '2026-05-08T15:44:01.103Z'::timestamptz);
