-- Mathieu Gagnon-Leblanc
INSERT INTO portfolio_items (id, profile_id, project_name, organization, organization_id, start_year, end_year, role, description, results, images, links, video_url, sort_order) VALUES
  ('330ef714-ebf4-44bd-9864-f58cf3e72713', 'e0b081d3-8f5c-5ad2-9938-39236da09711', $$E-Learning Localization for Community Health Workers$$, $$Global health partnership$$, NULL, 2021, 2022, $$Localization Lead$$, $$Localized a 20-module e-learning course into French and Spanish, adapting examples for West and Central Africa and Latin America.$$, $$Course used by 15,000 health workers in 18 countries.$$, $$[{"url":"https://picsum.photos/seed/demo-mathieu-gagnon-leblanc-portfolio-1/600/400","caption":null},{"url":"https://picsum.photos/seed/demo-mathieu-gagnon-leblanc-portfolio-1-img1/900/600","caption":"Localized course screen"}]$$::jsonb, $$[]$$::jsonb, NULL, 1),
  ('843f4dc6-4476-4a30-8c0a-cfdd5ea444db', 'e0b081d3-8f5c-5ad2-9938-39236da09711', $$Campaign Transcreation for Girls' Education$$, $$Canadian NGO$$, NULL, 2023, 2023, $$Transcreator$$, $$Transcreated campaign slogans, scripts and social content into French and Spanish.$$, $$Campaign launched in five countries with locally adapted messaging.$$, $$[{"url":"https://picsum.photos/seed/demo-mathieu-gagnon-leblanc-portfolio-2/600/400","caption":null},{"url":"https://picsum.photos/seed/demo-mathieu-gagnon-leblanc-portfolio-2-img1/900/600","caption":"Campaign poster in French"}]$$::jsonb, $$[]$$::jsonb, NULL, 2),
  ('dd3e74cf-f36f-5e1a-acc0-8864c56dbca3', 'e0b081d3-8f5c-5ad2-9938-39236da09711', $$Subtitled Malaria Prevention Video Series$$, $$Global Fund to Fight AIDS, Tuberculosis and Malaria$$, (SELECT id FROM organizations WHERE name = $$Global Fund to Fight AIDS, Tuberculosis and Malaria$$), 2022, 2022, $$Translator and Subtitler$$, $$Translated and subtitled a series of twelve short malaria prevention videos for community health workers into French and Spanish, adapting terms with health workers in Burkina Faso and Guatemala.$$, $$Series used in community health worker training in nine countries.$$, $$[{"url":"https://picsum.photos/seed/demo-mathieu-gagnon-leblanc-subtitled-malaria-prevention-video-serie-1/900/600","caption":"Subtitling session"}]$$::jsonb, $$[]$$::jsonb, NULL, 3),
  ('877e2883-324e-563b-a01b-4f857f923e1c', 'e0b081d3-8f5c-5ad2-9938-39236da09711', $$French Localization of a Disability Inclusion Toolkit$$, $$CBM$$, (SELECT id FROM organizations WHERE name = $$CBM$$), 2024, 2024, $$Lead Translator$$, $$Localized a disability inclusion toolkit for programme staff into French for West and Central Africa, with plain-language versions and accessible formats.$$, $$Toolkit used by partners in six Francophone countries.$$, $$[{"url":"https://picsum.photos/seed/demo-mathieu-gagnon-leblanc-french-localization-of-a-disability-incl-1/900/600","caption":"Toolkit cover"}]$$::jsonb, $$[]$$::jsonb, NULL, 4);
INSERT INTO audio_testimonials (id, profile_id, work_history_entry_id, portfolio_item_id, reference_name, reference_org, reference_title, relationship, referee_email, referee_org_id, period_start, period_end, context, audio_path, transcript, transcript_source, transcript_confirmed_at, duration_seconds, source, submission_token, status, precheck_status, review_flags, opened_at, confirmed_at, details_accepted_at, consent_at, submitted_at, published_at, withdraw_token, created_at) VALUES ('e566070e-6f97-577a-8280-e3c4fde6e2ba', 'e0b081d3-8f5c-5ad2-9938-39236da09711', $$57eb8a40-6e18-42d1-ac5f-95692ad34940$$, NULL, $$Élise Fontaine$$, $$Global Fund to Fight AIDS, Tuberculosis and Malaria$$, $$Senior Communications Manager$$, $$supervisor$$, $$elise.fontaine@theglobalfund.org$$, (SELECT id FROM organizations WHERE name = $$Global Fund to Fight AIDS, Tuberculosis and Malaria$$), 2013, 2016, $$Translation at a global health partnership in Geneva$$, $$demo/testimonial-1.m4a$$, $$[Demo testimonial: fictional referee, synthetic audio] I supervised Mathieu at a global health partnership in Geneva before joining the Global Fund. He translated technical health materials with remarkable accuracy and adapted them for community audiences. He meets deadlines, asks the right questions and keeps a terminology base that others rely on. I would work with him again on any French or Spanish translation.$$, $$auto$$, '2026-06-25T15:44:01.103Z'::timestamptz, 48, $$reference_direct$$, NULL, 'published', 'passed', '[]'::jsonb, '2026-06-23T15:44:01.103Z'::timestamptz, '2026-06-25T15:29:37.103Z'::timestamptz, '2026-06-25T15:36:49.103Z'::timestamptz, '2026-06-25T15:44:01.103Z'::timestamptz, '2026-06-25T15:44:01.103Z'::timestamptz, '2026-06-26T15:44:01.103Z'::timestamptz, $$77ba4f358efedbc1949d3b72aa05bdff$$, '2026-06-22T15:44:01.103Z'::timestamptz);
