INSERT INTO video_responses (id, profile_id, kind, question_id, video_url, video_path, transcript, duration_seconds) VALUES
  ('2fec845c-6373-5f38-9772-3dfffe8a147f', 'e0b081d3-8f5c-5ad2-9938-39236da09711', 'question', (SELECT id FROM interview_questions WHERE sort_order = 1 AND active ORDER BY id LIMIT 1), NULL, $$demo/qna-1.mp4$$, $$[Demo answer] I'm proudest of localizing an e-learning course for community health workers. I led the French and Spanish versions. What changed is that health workers in Francophone Africa and Latin America completed the course at the same rate as English users.$$, 20),
  ('2cf6a248-4a30-571b-afee-f64d6add0bb2', 'e0b081d3-8f5c-5ad2-9938-39236da09711', 'question', (SELECT id FROM interview_questions WHERE sort_order = 2 AND active ORDER BY id LIMIT 1), NULL, $$demo/qna-2.mp4$$, $$[Demo answer] When I translated campaign materials for a context I didn't know, I asked local partners to test the words with real audiences before we finalised anything. Some phrases that work in Montreal mean something else in Dakar.$$, 20),
  ('afa3d710-3365-560b-8dd2-f4c62f93be31', 'e0b081d3-8f5c-5ad2-9938-39236da09711', 'question', (SELECT id FROM interview_questions WHERE sort_order = 3 AND active ORDER BY id LIMIT 1), NULL, $$demo/qna-3.mp4$$, $$[Demo answer] Once I had to tell a client that their source text contained errors that would mislead readers. I listed them clearly and suggested corrections, and the client fixed the English version too.$$, 20),
  ('a8f517bb-55d7-5c62-a1fb-ebf13e63e182', 'e0b081d3-8f5c-5ad2-9938-39236da09711', 'question', (SELECT id FROM interview_questions WHERE sort_order = 4 AND active ORDER BY id LIMIT 1), NULL, $$demo/qna-4.mp4$$, $$[Demo answer] Working across languages means working with local partners. I keep shared glossaries with them, so that health terms stay consistent across materials and countries.$$, 20),
  ('89851621-0e7e-5c6a-a343-f1ec1e2148f6', 'e0b081d3-8f5c-5ad2-9938-39236da09711', 'question', (SELECT id FROM interview_questions WHERE sort_order = 5 AND active ORDER BY id LIMIT 1), NULL, $$demo/qna-5.mp4$$, $$[Demo answer] I specialise in transcreation for campaigns. It is not the right approach for legal or technical documents, where a faithful translation matters more than an adapted message.$$, 20);
