  ('76fc1dd0-f964-532e-bfd1-179d1ceb8708', 'e0b081d3-8f5c-5ad2-9938-39236da09711', 'degree', $$1a638d9f-cf36-4073-ac19-108de046988d$$, $$BA Traduction, Université de Montréal, 2009–2012$$, '06ac01fe', 'document_reviewed', 'document', $${"note":"Demo: certificate checked for format, dates and consistency.","evidence":[{"kind":"file","mime_type":"application/pdf"}],"evidence_deleted_at":"2026-05-31T20:44:01.103Z"}$$::jsonb, 'admin', $$Demo Admin$$, '2026-05-31T21:44:01.103Z'::timestamptz);

-- Salma El Idrissi
INSERT INTO portfolio_items (id, profile_id, project_name, organization, organization_id, start_year, end_year, role, description, results, images, links, video_url, sort_order) VALUES
  ('c5229dc6-cb36-42cd-9eba-b76d154e425d', '48fe6665-9238-5e21-b240-465e05bb93c2', $$Gender Budget Statement Support, Tunisia$$, $$UN Women$$, (SELECT id FROM organizations WHERE name = $$UN Women$$), 2019, 2021, $$Lead Advisor$$, $$Advised the Ministry of Finance on introducing a gender budget statement and trained budget officers in eight ministries.$$, $$First gender budget statement annexed to the 2021 finance law.$$, $$[{"url":"https://picsum.photos/seed/demo-salma-el-idrissi-portfolio-1/600/400","caption":null},{"url":"https://picsum.photos/seed/demo-salma-el-idrissi-portfolio-1-img1/900/600","caption":"Training of budget officers in Tunis"},{"url":"https://picsum.photos/seed/demo-salma-el-idrissi-portfolio-1-img2/900/600","caption":"Validation meeting"}]$$::jsonb, $$[]$$::jsonb, NULL, 1),
  ('9a8f3640-642e-4b25-88ef-9f44dd5bec4c', '48fe6665-9238-5e21-b240-465e05bb93c2', $$Gender Impact of Tax Reform, Morocco$$, $$OECD$$, (SELECT id FROM organizations WHERE name = $$OECD$$), 2022, 2022, $$Policy Analyst$$, $$Analysed the gender impact of proposed personal income tax and VAT reforms.$$, $$Analysis informed adjustments to family deductions.$$, $$[{"url":"https://picsum.photos/seed/demo-salma-el-idrissi-portfolio-2/600/400","caption":null},{"url":"https://picsum.photos/seed/demo-salma-el-idrissi-portfolio-2-img1/900/600","caption":"Presentation to parliament's finance committee"}]$$::jsonb, $$[]$$::jsonb, NULL, 2),
  ('41debfd7-2b3d-562e-8276-49c36f254798', '48fe6665-9238-5e21-b240-465e05bb93c2', $$Gender Budget Centre of Excellence, Morocco$$, $$Ministère de l'Économie et des Finances, Morocco$$, NULL, 2012, 2016, $$Coordinator$$, $$Set up and ran the ministry's centre of excellence for gender-responsive budgeting: annual gender budget report, training for line ministries, and a knowledge platform shared with other countries in the region.$$, $$Gender budget report annexed to the finance law every year since 2013; 27 ministries reporting.$$, $$[{"url":"https://picsum.photos/seed/demo-salma-el-idrissi-gender-budget-centre-of-excellence-moroc-1/900/600","caption":"Training for line ministries"},{"url":"https://picsum.photos/seed/demo-salma-el-idrissi-gender-budget-centre-of-excellence-moroc-2/900/600","caption":"Gender budget report launch"}]$$::jsonb, $$[]$$::jsonb, NULL, 3),
  ('646ca363-199b-5f31-bc4d-acc9766a3372', '48fe6665-9238-5e21-b240-465e05bb93c2', $$Gender-Responsive PFM Training for Arab Parliaments$$, $$UNDP$$, (SELECT id FROM organizations WHERE name = $$UNDP$$), 2023, 2023, $$Lead Trainer$$, $$Designed and delivered a training course for parliamentary budget committees in four Arab countries on reading budgets through a gender lens and questioning ministers on results.$$, $$60 members of parliament and staff trained; two committees added gender questions to budget hearings.$$, $$[{"url":"https://picsum.photos/seed/demo-salma-el-idrissi-gender-responsive-pfm-training-for-arab--1/900/600","caption":"Training session in Amman"}]$$::jsonb, $$[]$$::jsonb, NULL, 4);
INSERT INTO audio_testimonials (id, profile_id, work_history_entry_id, portfolio_item_id, reference_name, reference_org, reference_title, relationship, referee_email, referee_org_id, period_start, period_end, context, audio_path, transcript, transcript_source, transcript_confirmed_at, duration_seconds, source, submission_token, status, precheck_status, review_flags, opened_at, confirmed_at, details_accepted_at, consent_at, submitted_at, published_at, withdraw_token, created_at) VALUES ('a70b3b75-04e0-5e09-9e65-d3404a231105', '48fe6665-9238-5e21-b240-465e05bb93c2', $$13ed061a-5518-4c99-85dc-095beeacc27c$$, NULL, $$Nadia Benjelloun$$, $$UN Women$$, $$Regional Programme Specialist, Gender-Responsive Budgeting$$, $$supervisor$$, $$nadia.benjelloun@unwomen.org$$, (SELECT id FROM organizations WHERE name = $$UN Women$$), 2006, 2016, $$Gender budget centre of excellence at Morocco's finance ministry$$, $$demo/testimonial-2.m4a$$, $$[Demo testimonial: fictional referee, synthetic audio] I directed the department where Salma built Morocco's gender budget centre of excellence, before I joined UN Women. She turned a political commitment into an annual report that ministries take seriously. She is an outstanding public finance expert and a patient trainer. I would work with her again on any gender budgeting assignment.$$, $$auto$$, '2026-05-16T15:44:01.103Z'::timestamptz, 62, $$reference_direct$$, NULL, 'published', 'passed', '[]'::jsonb, '2026-05-14T15:44:01.103Z'::timestamptz, '2026-05-16T15:29:37.103Z'::timestamptz, '2026-05-16T15:36:49.103Z'::timestamptz, '2026-05-16T15:44:01.103Z'::timestamptz, '2026-05-16T15:44:01.103Z'::timestamptz, '2026-05-17T15:44:01.103Z'::timestamptz, $$7167d6ca7723550b0069fe1988264205$$, '2026-05-13T15:44:01.103Z'::timestamptz);
