INSERT INTO audio_testimonials (id, profile_id, work_history_entry_id, portfolio_item_id, reference_name, reference_org, reference_title, relationship, referee_email, referee_org_id, period_start, period_end, context, audio_path, transcript, transcript_source, transcript_confirmed_at, duration_seconds, source, submission_token, status, precheck_status, review_flags, opened_at, confirmed_at, details_accepted_at, consent_at, submitted_at, published_at, withdraw_token, created_at) VALUES ('6d177aa0-43f9-53bd-8531-0791ad35dae9', '48fe6665-9238-5e21-b240-465e05bb93c2', NULL, '9a8f3640-642e-4b25-88ef-9f44dd5bec4c', $$Thomas Girard$$, $$OECD$$, $$Senior Policy Analyst, Gender Budgeting$$, $$client$$, $$thomas.girard@oecd.org$$, (SELECT id FROM organizations WHERE name = $$OECD$$), 2022, 2022, $$Gender impact of tax reform in Morocco$$, $$demo/testimonial-3.m4a$$, $$[Demo testimonial: fictional referee, synthetic audio] We commissioned Salma to analyse the gender impact of Morocco's tax reform. Her analysis was rigorous, and she knew exactly which data the ministry held and how to get it. Her findings fed into our regional report on gender and tax. I would work with her again.$$, $$auto$$, '2026-09-03T15:44:01.103Z'::timestamptz, 75, $$reference_direct$$, NULL, 'published', 'passed', '[]'::jsonb, '2026-09-01T15:44:01.103Z'::timestamptz, '2026-09-03T15:29:37.103Z'::timestamptz, '2026-09-03T15:36:49.103Z'::timestamptz, '2026-09-03T15:44:01.103Z'::timestamptz, '2026-09-03T15:44:01.103Z'::timestamptz, '2026-09-04T15:44:01.103Z'::timestamptz, $$370389e658ea60ee5f9007b0f51cd26e$$, '2026-08-31T15:44:01.103Z'::timestamptz);
