INSERT INTO video_responses (id, profile_id, kind, question_id, video_url, video_path, transcript, duration_seconds) VALUES
  ('ff4b6cd0-6770-5695-a213-fddaac65010a', '48fe6665-9238-5e21-b240-465e05bb93c2', 'question', (SELECT id FROM interview_questions WHERE sort_order = 1 AND active ORDER BY id LIMIT 1), NULL, $$demo/qna-1.mp4$$, $$[Demo answer] I'm proudest of building Morocco's gender budget centre of excellence. I coordinated it for four years. What changed is that every ministry now reports on gender in the budget, and the report is annexed to the finance law every year.$$, 20),
  ('5faad9a6-760b-5c8e-abf0-e2ade464c787', '48fe6665-9238-5e21-b240-465e05bb93c2', 'question', (SELECT id FROM interview_questions WHERE sort_order = 2 AND active ORDER BY id LIMIT 1), NULL, $$demo/qna-2.mp4$$, $$[Demo answer] In Tunisia I supported a gender budget statement in a ministry I didn't know. I worked through Tunisian colleagues and spent time understanding the budget calendar before proposing anything.$$, 20),
  ('ce7af446-53e5-55a8-bd1b-aae69ed08bf5', '48fe6665-9238-5e21-b240-465e05bb93c2', 'question', (SELECT id FROM interview_questions WHERE sort_order = 3 AND active ORDER BY id LIMIT 1), NULL, $$demo/qna-3.mp4$$, $$[Demo answer] Once our analysis showed that a flagship programme benefited men far more than women. I presented it privately to the ministry first, with options to fix the targeting, so it became an improvement rather than an embarrassment.$$, 20),
  ('4863f666-d8fe-52f4-bffe-878ff078c4ef', '48fe6665-9238-5e21-b240-465e05bb93c2', 'question', (SELECT id FROM interview_questions WHERE sort_order = 4 AND active ORDER BY id LIMIT 1), NULL, $$demo/qna-4.mp4$$, $$[Demo answer] I work in Arabic, French, English and Tamazight. Budget reform only lasts when national teams own it, so I train trainers and step back.$$, 20),
  ('6f8ab9bc-436b-50b6-9e88-a0b600cb1c11', '48fe6665-9238-5e21-b240-465e05bb93c2', 'question', (SELECT id FROM interview_questions WHERE sort_order = 5 AND active ORDER BY id LIMIT 1), NULL, $$demo/qna-5.mp4$$, $$[Demo answer] I specialise in gender budget tagging. It is not the right tool when budget execution data is unreliable; then you need to strengthen financial reporting first.$$, 20);
