  ('bec48b5b-5040-5c77-869e-eb487dcdc238', '48fe6665-9238-5e21-b240-465e05bb93c2', 'degree', $$c3292531-9b0d-4b52-8b65-91f2d95aa889$$, $$Doctorat en Sciences Économiques, Université Mohammed V de Rabat, 2000–2005$$, '6e492e17', 'document_reviewed', 'document', $${"note":"Demo: certificate checked for format, dates and consistency.","evidence":[{"kind":"file","mime_type":"application/pdf"}],"evidence_deleted_at":"2026-04-21T20:44:01.103Z"}$$::jsonb, 'admin', $$Demo Admin$$, '2026-04-21T21:44:01.103Z'::timestamptz);

-- Youssef Ben Amor
INSERT INTO portfolio_items (id, profile_id, project_name, organization, organization_id, start_year, end_year, role, description, results, images, links, video_url, sort_order) VALUES
  ('3b581f02-0952-4655-90c0-685d00b96869', 'a6e72473-3cd0-5066-a102-96b450f50c03', $$Investment Incentive Cost-Benefit Model, Tunisia$$, $$World Bank$$, (SELECT id FROM organizations WHERE name = $$World Bank$$), 2021, 2022, $$Financial Modeler$$, $$Built a cost-benefit model of investment incentives under the new investment law.$$, $$Government phased out two low-return incentives.$$, $$[{"url":"https://picsum.photos/seed/demo-youssef-ben-amor-portfolio-1/600/400","caption":null},{"url":"https://picsum.photos/seed/demo-youssef-ben-amor-portfolio-1-img1/900/600","caption":"Model review session"}]$$::jsonb, $$[]$$::jsonb, NULL, 1),
  ('cb009366-05b2-4cdd-a5f0-97bcf02eacb8', 'a6e72473-3cd0-5066-a102-96b450f50c03', $$Olive Oil Export Competitiveness Study$$, $$GIZ Tunisia$$, (SELECT id FROM organizations WHERE name = $$GIZ$$), 2020, 2020, $$Lead Economist$$, $$Analysed export performance, costs and market access for packaged olive oil.$$, $$Recommendations adopted in the sector export strategy.$$, $$[{"url":"https://picsum.photos/seed/demo-youssef-ben-amor-portfolio-2/600/400","caption":null},{"url":"https://picsum.photos/seed/demo-youssef-ben-amor-portfolio-2-img1/900/600","caption":"Olive oil mill in Sfax"}]$$::jsonb, $$[]$$::jsonb, NULL, 2),
  ('e9db0fd4-d98b-52fd-8a43-859b1fa9deec', 'a6e72473-3cd0-5066-a102-96b450f50c03', $$Tourism Investment Pipeline Review, Djerba$$, $$European Bank for Reconstruction and Development$$, (SELECT id FROM organizations WHERE name = $$European Bank for Reconstruction and Development$$), 2023, 2023, $$Investment Economist$$, $$Reviewed the pipeline of hotel and eco-tourism investments in Djerba, the incentives they relied on, and the infrastructure constraints, and estimated jobs and fiscal costs per project.$$, $$Three projects prioritised for financing; incentive conditions revised for two.$$, $$[{"url":"https://picsum.photos/seed/demo-youssef-ben-amor-tourism-investment-pipeline-review-djerb-1/900/600","caption":"Site visit to an eco-lodge"},{"url":"https://picsum.photos/seed/demo-youssef-ben-amor-tourism-investment-pipeline-review-djerb-2/900/600","caption":"Investor interviews"}]$$::jsonb, $$[]$$::jsonb, NULL, 3);
INSERT INTO audio_testimonials (id, profile_id, work_history_entry_id, portfolio_item_id, reference_name, reference_org, reference_title, relationship, referee_email, referee_org_id, period_start, period_end, context, audio_path, transcript, transcript_source, transcript_confirmed_at, duration_seconds, source, submission_token, status, precheck_status, review_flags, opened_at, confirmed_at, details_accepted_at, consent_at, submitted_at, published_at, withdraw_token, created_at) VALUES ('b6b8d23e-4b04-58af-a32d-917c0fd58e2c', 'a6e72473-3cd0-5066-a102-96b450f50c03', $$d6a6e0c7-c2dc-4dce-be2c-e0abcdb7fcca$$, NULL, $$Mehdi Trabelsi$$, $$World Bank$$, $$Senior Private Sector Specialist$$, $$supervisor$$, $$mtrabelsi@worldbank.org$$, (SELECT id FROM organizations WHERE name = $$World Bank$$), 2014, 2019, $$Economic analysis at Tunisia's foreign investment promotion agency$$, $$demo/testimonial-4.m4a$$, $$[Demo testimonial: fictional referee, synthetic audio] I supervised Youssef at Tunisia's foreign investment promotion agency before I joined the World Bank. He built the agency's first cost-benefit model for investment incentives and defended it calmly in front of sceptical officials. He is a careful economist and a clear writer. I would work with him again on investment and trade.$$, $$auto$$, '2026-06-15T15:44:01.103Z'::timestamptz, 88, $$reference_direct$$, NULL, 'published', 'passed', '[]'::jsonb, '2026-06-13T15:44:01.103Z'::timestamptz, '2026-06-15T15:29:37.103Z'::timestamptz, '2026-06-15T15:36:49.103Z'::timestamptz, '2026-06-15T15:44:01.103Z'::timestamptz, '2026-06-15T15:44:01.103Z'::timestamptz, '2026-06-16T15:44:01.103Z'::timestamptz, $$37ae999da9ea492bc6968651f33f09fe$$, '2026-06-12T15:44:01.103Z'::timestamptz);
