-- Mai Abdel-Aziz Fawzy
INSERT INTO portfolio_items (id, profile_id, project_name, organization, organization_id, start_year, end_year, role, description, results, images, links, video_url, sort_order) VALUES
  ('5338c035-e898-4e45-b498-c7cfd1e39dbb', '59e4a332-ed54-513b-84bd-be3126f24d22', $$Recycled Plastics Market Assessment, Greater Cairo$$, $$European Union$$, (SELECT id FROM organizations WHERE name = $$European Union$$), 2022, 2023, $$Market Research Lead$$, $$Assessed supply and demand for recycled plastics, with a survey of 400 informal collectors and 30 recyclers.$$, $$Findings shaped an EU-funded recycling SME grant window.$$, $$[{"url":"https://picsum.photos/seed/demo-mai-abdel-aziz-fawzy-portfolio-1/600/400","caption":null},{"url":"https://picsum.photos/seed/demo-mai-abdel-aziz-fawzy-portfolio-1-img1/900/600","caption":"Sorting in Manshiyat Naser"}]$$::jsonb, $$[]$$::jsonb, NULL, 1),
  ('2ae7b5db-8033-461d-8565-56d3e4f9f6d4', '59e4a332-ed54-513b-84bd-be3126f24d22', $$Agricultural Residue Value Chains, Upper Egypt$$, $$UNIDO$$, (SELECT id FROM organizations WHERE name = $$UNIDO$$), 2019, 2020, $$Value Chain Analyst$$, $$Mapped supply chains for rice straw and sugarcane residues used in compost and boards.$$, $$Two pilot processing units established.$$, $$[{"url":"https://picsum.photos/seed/demo-mai-abdel-aziz-fawzy-portfolio-2/600/400","caption":null},{"url":"https://picsum.photos/seed/demo-mai-abdel-aziz-fawzy-portfolio-2-img1/900/600","caption":"Rice straw collection"}]$$::jsonb, $$[]$$::jsonb, NULL, 2),
  ('a2c604f5-c78f-50ca-b65e-1449e2eae3d9', '59e4a332-ed54-513b-84bd-be3126f24d22', $$Waste Pickers' Cooperative Support, Giza$$, $$UNIDO$$, (SELECT id FROM organizations WHERE name = $$UNIDO$$), 2020, 2021, $$Project Associate$$, $$Helped two waste pickers' cooperatives in Giza formalise, negotiate supply contracts with recyclers and improve sorting and safety, with a focus on women members.$$, $$Members' incomes rose by a quarter; both cooperatives signed supply contracts.$$, $$[{"url":"https://picsum.photos/seed/demo-mai-abdel-aziz-fawzy-waste-pickers-cooperative-support-giza-1/900/600","caption":"Sorting centre visit"},{"url":"https://picsum.photos/seed/demo-mai-abdel-aziz-fawzy-waste-pickers-cooperative-support-giza-2/900/600","caption":"Safety equipment training"}]$$::jsonb, $$[]$$::jsonb, NULL, 3);
INSERT INTO audio_testimonials (id, profile_id, work_history_entry_id, portfolio_item_id, reference_name, reference_org, reference_title, relationship, referee_email, referee_org_id, period_start, period_end, context, audio_path, transcript, transcript_source, transcript_confirmed_at, duration_seconds, source, submission_token, status, precheck_status, review_flags, opened_at, confirmed_at, details_accepted_at, consent_at, submitted_at, published_at, withdraw_token, created_at) VALUES ('46e85691-1a5c-5c7a-a635-26523b52fc18', '59e4a332-ed54-513b-84bd-be3126f24d22', $$ae09f2e3-3c59-40b9-996e-73ef4c6bb1e3$$, NULL, $$Dr. Hany Mahmoud$$, $$UNIDO$$, $$Programme Officer, Circular Economy$$, $$supervisor$$, $$h.mahmoud@unido.org$$, (SELECT id FROM organizations WHERE name = $$UNIDO$$), 2017, 2021, $$Circular economy projects in Egypt$$, $$demo/testimonial-5.m4a$$, $$[Demo testimonial: fictional referee, synthetic audio] Mai worked with me at UNIDO Egypt for four years. Her agricultural residue value chain study opened a new area of work for us, and she was excellent with farmers, cooperatives and companies alike. She is rigorous with market data and practical about what businesses will do. I would work with her again on circular economy projects.$$, $$auto$$, '2026-07-20T15:44:01.103Z'::timestamptz, 97, $$reference_direct$$, NULL, 'published', 'passed', '[]'::jsonb, '2026-07-18T15:44:01.103Z'::timestamptz, '2026-07-20T15:29:37.103Z'::timestamptz, '2026-07-20T15:36:49.103Z'::timestamptz, '2026-07-20T15:44:01.103Z'::timestamptz, '2026-07-20T15:44:01.103Z'::timestamptz, '2026-07-21T15:44:01.103Z'::timestamptz, $$f0b3523d334c694fac8c1446c0ce54e8$$, '2026-07-17T15:44:01.103Z'::timestamptz);
