-- Hiba Osman Elfaki
INSERT INTO portfolio_items (id, profile_id, project_name, organization, organization_id, start_year, end_year, role, description, results, images, links, video_url, sort_order) VALUES
  ('454650f8-c4a5-4dca-92d1-fbfbdd56ac47', 'e9f12311-a907-520a-81a0-65b06cbb301b', $$Remote Monitoring of Cash Assistance, Gezira and Khartoum$$, $$World Food Programme$$, (SELECT id FROM organizations WHERE name = $$World Food Programme$$), 2023, 2024, $$MEAL Manager$$, $$Set up phone-based post-distribution monitoring of cash assistance for displaced households.$$, $$Monitoring covered 9,000 households and flagged access problems within days.$$, $$[{"url":"https://picsum.photos/seed/demo-hiba-osman-elfaki-portfolio-1/600/400","caption":null},{"url":"https://picsum.photos/seed/demo-hiba-osman-elfaki-portfolio-1-img1/900/600","caption":"Remote monitoring call centre"}]$$::jsonb, $$[]$$::jsonb, NULL, 1),
  ('32f12296-f33f-4848-b10c-c073179f2938', 'e9f12311-a907-520a-81a0-65b06cbb301b', $$Returnee and Refugee Assessment, White Nile$$, $$UNHCR Sudan$$, (SELECT id FROM organizations WHERE name = $$UNHCR$$), 2022, 2022, $$Survey Coordinator$$, $$Coordinated a household survey of South Sudanese refugees and Sudanese returnees on food security and services.$$, $$Assessment guided the joint response plan for the state.$$, $$[{"url":"https://picsum.photos/seed/demo-hiba-osman-elfaki-portfolio-2/600/400","caption":null},{"url":"https://picsum.photos/seed/demo-hiba-osman-elfaki-portfolio-2-img1/900/600","caption":"Survey team in Kosti"}]$$::jsonb, $$[]$$::jsonb, NULL, 2),
  ('d6dc69ea-c2e9-55b9-83af-976d46b1b808', 'e9f12311-a907-520a-81a0-65b06cbb301b', $$Community Feedback Hotline Analysis, Gedaref$$, $$World Food Programme$$, (SELECT id FROM organizations WHERE name = $$World Food Programme$$), 2024, 2024, $$MEAL Manager$$, $$Analysed 9,000 calls to the community feedback hotline for food and cash assistance, built a monthly dashboard of complaints by type and location, and followed up cases with field teams.$$, $$Average time to close complaints fell from 30 to 9 days.$$, $$[{"url":"https://picsum.photos/seed/demo-hiba-osman-elfaki-community-feedback-hotline-analysis-geda-1/900/600","caption":"Hotline dashboard"},{"url":"https://picsum.photos/seed/demo-hiba-osman-elfaki-community-feedback-hotline-analysis-geda-2/900/600","caption":"Feedback review with field teams"}]$$::jsonb, $$[]$$::jsonb, NULL, 3);
INSERT INTO audio_testimonials (id, profile_id, work_history_entry_id, portfolio_item_id, reference_name, reference_org, reference_title, relationship, referee_email, referee_org_id, period_start, period_end, context, audio_path, transcript, transcript_source, transcript_confirmed_at, duration_seconds, source, submission_token, status, precheck_status, review_flags, opened_at, confirmed_at, details_accepted_at, consent_at, submitted_at, published_at, withdraw_token, created_at) VALUES ('880b6a4a-7f0b-53b1-aa0c-7e17320e6e9d', 'e9f12311-a907-520a-81a0-65b06cbb301b', $$f27ef6d3-512e-4588-9888-0a87df7a6c32$$, NULL, $$Amira Hassan$$, $$World Food Programme$$, $$Monitoring and Evaluation Officer$$, $$client$$, $$amira.hassan@wfp.org$$, (SELECT id FROM organizations WHERE name = $$World Food Programme$$), 2023, 2024, $$Remote monitoring of cash assistance in Gezira and Khartoum$$, $$demo/testimonial-6.m4a$$, $$[Demo testimonial: fictional referee, synthetic audio] We worked with Hiba on remote monitoring of our cash assistance in Gezira and Khartoum. She kept monitoring going through the war, with careful protection of her teams and of beneficiaries' data. Her reports were accurate and on time. I would work with her again on humanitarian monitoring.$$, $$auto$$, '2026-09-08T15:44:01.103Z'::timestamptz, 110, $$reference_direct$$, NULL, 'published', 'passed', '[]'::jsonb, '2026-09-06T15:44:01.103Z'::timestamptz, '2026-09-08T15:29:37.103Z'::timestamptz, '2026-09-08T15:36:49.103Z'::timestamptz, '2026-09-08T15:44:01.103Z'::timestamptz, '2026-09-08T15:44:01.103Z'::timestamptz, '2026-09-09T15:44:01.103Z'::timestamptz, $$e4250ca85d5c7e87856dc3ec619ddf7d$$, '2026-09-05T15:44:01.103Z'::timestamptz);
