INSERT INTO portfolio_items (id, profile_id, project_name, organization, organization_id, start_year, end_year, role, description, results, images, links, video_url, sort_order) VALUES
  ('fc26a4ba-49c2-4b54-b633-26395da0b0bc', '329cd0eb-e66e-5856-8fa1-5fdb36e20f38', $$Housing Rehabilitation for Returnees, Sinjar$$, $$UNDP Iraq$$, (SELECT id FROM organizations WHERE name = $$UNDP$$), 2020, 2023, $$Programme Manager$$, $$Managed rehabilitation of 2,300 houses and water networks for returning Yazidi families.$$, $$Return rates in target villages doubled over the programme.$$, $$[{"url":"https://picsum.photos/seed/demo-shilan-kareem-mahmoud-portfolio-1/600/400","caption":null},{"url":"https://picsum.photos/seed/demo-shilan-kareem-mahmoud-portfolio-1-img1/900/600","caption":"Rehabilitated houses in Sinjar"}]$$::jsonb, $$[]$$::jsonb, NULL, 1),
  ('942a6adf-aac3-4b4f-8cb9-e55601aacdc3', '329cd0eb-e66e-5856-8fa1-5fdb36e20f38', $$Camp Services for Syrian Refugees, Domiz$$, $$International NGO (Erbil)$$, NULL, 2014, 2018, $$Project Manager$$, $$Managed water, sanitation and community services in a refugee camp of 30,000 people.$$, $$Maintained services through two winter emergencies.$$, $$[{"url":"https://picsum.photos/seed/demo-shilan-kareem-mahmoud-portfolio-2/600/400","caption":null},{"url":"https://picsum.photos/seed/demo-shilan-kareem-mahmoud-portfolio-2-img1/900/600","caption":"Community centre in Domiz"}]$$::jsonb, $$[]$$::jsonb, NULL, 2),
  ('057a092b-9234-554f-94cc-f44e86a7e503', '329cd0eb-e66e-5856-8fa1-5fdb36e20f38', $$Safeguards Screening for Reconstruction Sites, Ninewa$$, $$UNDP$$, (SELECT id FROM organizations WHERE name = $$UNDP$$), 2022, 2023, $$Programme Manager$$, $$Set up environmental and social screening for 400 reconstruction sites in Ninewa, covering explosive hazard clearance, rubble disposal, land ownership and community consultation.$$, $$All sites screened before works; no land disputes escalated during construction.$$, $$[{"url":"https://picsum.photos/seed/demo-shilan-kareem-mahmoud-safeguards-screening-for-reconstruction--1/900/600","caption":"Site screening visit"},{"url":"https://picsum.photos/seed/demo-shilan-kareem-mahmoud-safeguards-screening-for-reconstruction--2/900/600","caption":"Community consultation in Sinjar"}]$$::jsonb, $$[]$$::jsonb, NULL, 3);
