INSERT INTO portfolio_items (id, profile_id, project_name, organization, organization_id, start_year, end_year, role, description, results, images, links, video_url, sort_order) VALUES
  ('5f1b7ece-1621-4fbd-9029-ba148465d98d', 'bd5ed935-89fd-5a53-b3b6-7cab3dd2df08', $$Earthquake Response Warehouse Coordination$$, $$Logistics Cluster$$, NULL, 2023, 2023, $$Logistics Officer$$, $$Coordinated warehouse data and dispatches for relief items after the February 2023 earthquakes.$$, $$Dispatch tracking cut lost consignments in the first month.$$, $$[{"url":"https://picsum.photos/seed/demo-elif-kaya-demir-portfolio-1/600/400","caption":null},{"url":"https://picsum.photos/seed/demo-elif-kaya-demir-portfolio-1-img1/900/600","caption":"Warehouse in Gaziantep"}]$$::jsonb, $$[]$$::jsonb, NULL, 1),
  ('985d33c7-5a39-463b-b9c1-5ca6af97dc60', 'bd5ed935-89fd-5a53-b3b6-7cab3dd2df08', $$Cross-Border Shipment Tracking Database$$, $$International NGO (Gaziantep)$$, NULL, 2021, 2022, $$Database Administrator$$, $$Built and maintained a database tracking cross-border shipments to north-west Syria.$$, $$Database adopted by three partner agencies.$$, $$[{"url":"https://picsum.photos/seed/demo-elif-kaya-demir-portfolio-2/600/400","caption":null},{"url":"https://picsum.photos/seed/demo-elif-kaya-demir-portfolio-2-img1/900/600","caption":"Shipment tracking report"}]$$::jsonb, $$[]$$::jsonb, NULL, 2),
  ('db7dbb9b-6228-5284-988c-253deb2a07f8', 'bd5ed935-89fd-5a53-b3b6-7cab3dd2df08', $$Earthquake Contingency Stock Plan, South-East Türkiye$$, $$IFRC$$, (SELECT id FROM organizations WHERE name = $$IFRC$$), 2024, 2024, $$Logistics Officer$$, $$Planned contingency stocks of shelter and household items for future earthquakes in four provinces, with warehouse locations, supplier framework agreements and a stock dashboard.$$, $$Stocks for 10,000 households prepositioned; framework agreements with five suppliers.$$, $$[{"url":"https://picsum.photos/seed/demo-elif-kaya-demir-earthquake-contingency-stock-plan-south--1/900/600","caption":"Warehouse audit"},{"url":"https://picsum.photos/seed/demo-elif-kaya-demir-earthquake-contingency-stock-plan-south--2/900/600","caption":"Stock dashboard"}]$$::jsonb, $$[]$$::jsonb, NULL, 3);
INSERT INTO audio_testimonials (id, profile_id, work_history_entry_id, portfolio_item_id, reference_name, reference_org, reference_title, relationship, referee_email, referee_org_id, period_start, period_end, context, audio_path, transcript, transcript_source, transcript_confirmed_at, duration_seconds, source, submission_token, status, precheck_status, review_flags, opened_at, confirmed_at, details_accepted_at, consent_at, submitted_at, published_at, withdraw_token, created_at) VALUES ('45f72da9-725c-548c-83f8-01357654c816', 'bd5ed935-89fd-5a53-b3b6-7cab3dd2df08', $$f5e883e6-d767-4483-9340-f027e1ea7ca1$$, NULL, $$Mustafa Yilmaz$$, $$World Food Programme$$, $$Logistics Officer$$, $$supervisor$$, $$mustafa.yilmaz@wfp.org$$, (SELECT id FROM organizations WHERE name = $$World Food Programme$$), 2021, 2023, $$Logistics at an international NGO in Gaziantep$$, $$demo/testimonial-2.m4a$$, $$[Demo testimonial: fictional referee, synthetic audio] I supervised Elif at an international NGO in Gaziantep before I joined WFP. She built our shipment tracking database and kept it accurate during the earthquake response, when everything was chaos. She is organised, calm and quick to learn. I would work with her again on humanitarian logistics.$$, $$auto$$, '2026-08-14T15:44:01.103Z'::timestamptz, 62, $$reference_direct$$, NULL, 'published', 'passed', '[]'::jsonb, '2026-08-12T15:44:01.103Z'::timestamptz, '2026-08-14T15:29:37.103Z'::timestamptz, '2026-08-14T15:36:49.103Z'::timestamptz, '2026-08-14T15:44:01.103Z'::timestamptz, '2026-08-14T15:44:01.103Z'::timestamptz, '2026-08-15T15:44:01.103Z'::timestamptz, $$a2d6ade651a87d453f2212bc157b45c0$$, '2026-08-11T15:44:01.103Z'::timestamptz);
