INSERT INTO portfolio_items (id, profile_id, project_name, organization, organization_id, start_year, end_year, role, description, results, images, links, video_url, sort_order) VALUES
  ('8a23e7a1-85f0-4db4-bf66-e96d1fb7bf83', '9bb27515-fdd2-50f6-a57c-d4318d104275', $$Edited Volume on African Universities$$, $$University research consortium$$, NULL, 2021, 2022, $$Editor$$, $$Edited a 20-chapter volume by African scholars on university governance and research.$$, $$Published open access and widely downloaded.$$, $$[{"url":"https://picsum.photos/seed/demo-thomas-ashworth-portfolio-1/600/400","caption":null},{"url":"https://picsum.photos/seed/demo-thomas-ashworth-portfolio-1-img1/900/600","caption":"Book cover"}]$$::jsonb, $$[]$$::jsonb, NULL, 1),
  ('ea0a1781-c740-48ca-b09b-9e8d5e87f85e', '9bb27515-fdd2-50f6-a57c-d4318d104275', $$Flagship Report Restructure$$, $$International organization$$, NULL, 2019, 2019, $$Editor and Writer$$, $$Restructured and edited a flagship report on education financing.$$, $$Report published on time with a shorter, clearer structure.$$, $$[{"url":"https://picsum.photos/seed/demo-thomas-ashworth-portfolio-2/600/400","caption":null},{"url":"https://picsum.photos/seed/demo-thomas-ashworth-portfolio-2-img1/900/600","caption":"Report spread"}]$$::jsonb, $$[]$$::jsonb, NULL, 2),
  ('d6e36b5b-77bf-58b7-be3a-f250ec5e9535', '9bb27515-fdd2-50f6-a57c-d4318d104275', $$Editorial Style Guide for a Research Institute$$, $$ODI$$, (SELECT id FROM organizations WHERE name = $$ODI$$), 2023, 2023, $$Editorial Consultant$$, $$Wrote an editorial style guide and report templates for a development research institute, covering structure, plain language, data presentation and referencing, and trained the publications team.$$, $$Guide used for all publications; editing time per report down by a third.$$, $$[{"url":"https://picsum.photos/seed/demo-thomas-ashworth-editorial-style-guide-for-a-research-ins-1/900/600","caption":"Style guide training"}]$$::jsonb, $$[]$$::jsonb, NULL, 3);
INSERT INTO audio_testimonials (id, profile_id, work_history_entry_id, portfolio_item_id, reference_name, reference_org, reference_title, relationship, referee_email, referee_org_id, period_start, period_end, context, audio_path, transcript, transcript_source, transcript_confirmed_at, duration_seconds, source, submission_token, status, precheck_status, review_flags, opened_at, confirmed_at, details_accepted_at, consent_at, submitted_at, published_at, withdraw_token, created_at) VALUES ('d0b98d90-21d3-5cfe-91f9-dfe8c9e0ff64', '9bb27515-fdd2-50f6-a57c-d4318d104275', $$ee402f3e-f686-4a00-a021-120901fcf94a$$, NULL, $$Dr. Eleanor Wright$$, $$University of Oxford$$, $$Senior Research Fellow$$, $$supervisor$$, $$eleanor.wright@ox.ac.uk$$, (SELECT id FROM organizations WHERE name = $$University of Oxford$$), 2004, 2014, $$Development studies list at a university press$$, $$demo/testimonial-3.m4a$$, $$[Demo testimonial: fictional referee, synthetic audio] I worked with Thomas for ten years when he was editorial director for development studies at the press, and I now commission him regularly. He improves manuscripts without imposing himself on them. He is meticulous, kind to authors and always on time. I would work with him again on any book or report.$$, $$auto$$, '2026-02-25T15:44:01.103Z'::timestamptz, 75, $$reference_direct$$, NULL, 'published', 'passed', '[]'::jsonb, '2026-02-23T15:44:01.103Z'::timestamptz, '2026-02-25T15:29:37.103Z'::timestamptz, '2026-02-25T15:36:49.103Z'::timestamptz, '2026-02-25T15:44:01.103Z'::timestamptz, '2026-02-25T15:44:01.103Z'::timestamptz, '2026-02-26T15:44:01.103Z'::timestamptz, $$83429c2d4deaf65647f4cb0598e77504$$, '2026-02-22T15:44:01.103Z'::timestamptz);
