INSERT INTO portfolio_items (id, profile_id, project_name, organization, organization_id, start_year, end_year, role, description, results, images, links, video_url, sort_order) VALUES
  ('37c08c8b-de30-4e51-9399-de6bc4d0698d', 'b508465a-b1b3-586d-b5b2-b2a3302df9ea', $$Undernourishment Estimates from Household Surveys$$, $$FAO$$, (SELECT id FROM organizations WHERE name = $$FAO$$), 2018, 2021, $$Statistician$$, $$Developed methods to estimate the prevalence of undernourishment from household consumption surveys.$$, $$Methods used for 40 countries in global food security reporting.$$, $$[{"url":"https://picsum.photos/seed/demo-giulia-ferraro-benedetti-portfolio-1/600/400","caption":null},{"url":"https://picsum.photos/seed/demo-giulia-ferraro-benedetti-portfolio-1-img1/900/600","caption":"Indicator methods workshop"}]$$::jsonb, $$[]$$::jsonb, NULL, 1),
  ('22cd7a99-4f75-4949-a8a8-be172ebda24b', 'b508465a-b1b3-586d-b5b2-b2a3302df9ea', $$Nutrition Surveillance Toolkit in R$$, $$UNICEF$$, (SELECT id FROM organizations WHERE name = $$UNICEF$$), 2022, 2023, $$Data Scientist$$, $$Built an R toolkit for cleaning and analysing anthropometric survey data.$$, $$Toolkit used by nutrition clusters in six countries.$$, $$[{"url":"https://picsum.photos/seed/demo-giulia-ferraro-benedetti-portfolio-2/600/400","caption":null},{"url":"https://picsum.photos/seed/demo-giulia-ferraro-benedetti-portfolio-2-img1/900/600","caption":"Toolkit training session"}]$$::jsonb, $$[]$$::jsonb, NULL, 2),
  ('81407ecf-88f1-5b66-8db3-74f526959011', 'b508465a-b1b3-586d-b5b2-b2a3302df9ea', $$Fish Consumption Module for Household Surveys$$, $$FAO$$, (SELECT id FROM organizations WHERE name = $$FAO$$), 2019, 2020, $$Statistician$$, $$Designed and tested a fish and aquatic food consumption module for national household surveys, with guidance for national statistics offices on processing and analysis.$$, $$Module adopted in four national surveys.$$, $$[{"url":"https://picsum.photos/seed/demo-giulia-ferraro-benedetti-fish-consumption-module-for-household-su-1/900/600","caption":"Module testing with enumerators"}]$$::jsonb, $$[]$$::jsonb, NULL, 3),
  ('995dd2a6-8c73-5a45-bfe6-deab1818df31', 'b508465a-b1b3-586d-b5b2-b2a3302df9ea', $$Food Price Monitoring Dashboard$$, $$World Food Programme$$, (SELECT id FROM organizations WHERE name = $$World Food Programme$$), 2023, 2024, $$Data Scientist$$, $$Built an R pipeline and dashboard that combines market price data from eight countries, flags unusual price rises and estimates the cost of a minimum food basket.$$, $$Dashboard used in monthly market bulletins in eight countries.$$, $$[{"url":"https://picsum.photos/seed/demo-giulia-ferraro-benedetti-food-price-monitoring-dashboard-1/900/600","caption":"Price dashboard"}]$$::jsonb, $$[]$$::jsonb, NULL, 4);
