INSERT INTO video_responses (id, profile_id, kind, question_id, video_url, video_path, transcript, duration_seconds) VALUES
  ('f585926a-9ecd-552c-b38d-b7f02f823aab', 'b508465a-b1b3-586d-b5b2-b2a3302df9ea', 'question', (SELECT id FROM interview_questions WHERE sort_order = 1 AND active ORDER BY id LIMIT 1), NULL, $$demo/qna-1.mp4$$, $$[Demo answer] I'm proudest of improving undernourishment estimates from household surveys at FAO. I led the methodology. What changed is that more countries now report the indicator from their own surveys instead of relying on modelled estimates.$$, 20),
  ('1530b1d7-bc2a-5d14-94dc-ef275335b830', 'b508465a-b1b3-586d-b5b2-b2a3302df9ea', 'question', (SELECT id FROM interview_questions WHERE sort_order = 2 AND active ORDER BY id LIMIT 1), NULL, $$demo/qna-2.mp4$$, $$[Demo answer] When I trained a statistics office in a country I didn't know, I started by looking at their actual survey files with them. It showed me where their real difficulties were.$$, 20),
  ('9f43755d-0eb0-5005-bb39-d43689cbb5fe', 'b508465a-b1b3-586d-b5b2-b2a3302df9ea', 'question', (SELECT id FROM interview_questions WHERE sort_order = 3 AND active ORDER BY id LIMIT 1), NULL, $$demo/qna-3.mp4$$, $$[Demo answer] Once our estimates showed that a country's situation was worse than official figures. I worked with the national statisticians to check every step together, so the result was theirs and could be defended.$$, 20),
  ('1a6ad605-ff8a-51ae-ab7a-a725ee71d52c', 'b508465a-b1b3-586d-b5b2-b2a3302df9ea', 'question', (SELECT id FROM interview_questions WHERE sort_order = 4 AND active ORDER BY id LIMIT 1), NULL, $$demo/qna-4.mp4$$, $$[Demo answer] I work in Italian, English, French and Spanish, and I always build tools that national teams can maintain. I write documentation first and code second.$$, 20),
  ('fc409bea-1fd3-51a4-90c5-31fc989c9b88', 'b508465a-b1b3-586d-b5b2-b2a3302df9ea', 'question', (SELECT id FROM interview_questions WHERE sort_order = 5 AND active ORDER BY id LIMIT 1), NULL, $$demo/qna-5.mp4$$, $$[Demo answer] I specialise in survey-based food security estimates. They are not the right tool for fast-changing crises; then market monitoring and phone surveys give answers in time.$$, 20);
