  ('6a3dd6c3-eb08-5236-8ff9-bec41c49ce80', 'b508465a-b1b3-586d-b5b2-b2a3302df9ea', 'employer', $$e03f98c5-3970-4807-b70c-df14d47eed72$$, $$Food Security Data Scientist, Independent consultant, 2021–present$$, 'bfe203dd', 'document_reviewed', 'document', $${"note":"Demo: contract with most recent client reviewed.","evidence":[{"kind":"file","mime_type":"application/pdf"}],"evidence_deleted_at":"2026-07-05T18:44:01.103Z"}$$::jsonb, 'admin', $$Demo Admin$$, '2026-07-05T19:44:01.103Z'::timestamptz),
  ('5aa5b7be-99fc-5168-a9b8-7ffabff5c409', 'b508465a-b1b3-586d-b5b2-b2a3302df9ea', 'degree', $$f28d533c-4228-49b8-a3f7-97d79a50753e$$, $$PhD Statistics, Sapienza University of Rome, 2011–2015$$, '0756fe09', 'confirmed', 'degree_service', $${"note":"Demo: confirmed by degree-verification service (placeholder)."}$$::jsonb, 'admin', $$Demo Admin$$, '2026-07-05T20:44:01.103Z'::timestamptz);

