INSERT INTO portfolio_items (id, profile_id, project_name, organization, organization_id, start_year, end_year, role, description, results, images, links, video_url, sort_order) VALUES
  ('95da3bd9-213e-4adb-a7f2-971e5b8ed067', '19e6abe5-7d45-5fc7-bf74-b6c9b5d77180', $$Climate Summit Advocacy Campaign$$, $$NGO coalition$$, NULL, 2021, 2021, $$Campaign Advisor$$, $$Advised an NGO coalition on advocacy and media relations around a climate summit.$$, $$Coalition messages featured in major European media.$$, $$[{"url":"https://picsum.photos/seed/demo-jonas-weber-lindqvist-portfolio-1/600/400","caption":null},{"url":"https://picsum.photos/seed/demo-jonas-weber-lindqvist-portfolio-1-img1/900/600","caption":"Press conference at the summit"}]$$::jsonb, $$[]$$::jsonb, NULL, 1),
  ('564f170c-76b5-4ed8-b4c4-7e9d7546dfa2', '19e6abe5-7d45-5fc7-bf74-b6c9b5d77180', $$Circular Economy Policy Brief Series$$, $$Climate think tank$$, NULL, 2019, 2020, $$Author$$, $$Wrote policy briefs on circular economy measures in EU climate policy.$$, $$Briefs cited in parliamentary consultations.$$, $$[{"url":"https://picsum.photos/seed/demo-jonas-weber-lindqvist-portfolio-2/600/400","caption":null},{"url":"https://picsum.photos/seed/demo-jonas-weber-lindqvist-portfolio-2-img1/900/600","caption":"Policy brief cover"}]$$::jsonb, $$[]$$::jsonb, NULL, 2),
  ('de48cc3b-347e-5b75-a65f-3276e5406162', '19e6abe5-7d45-5fc7-bf74-b6c9b5d77180', $$Briefing Pack on Article 6 Carbon Markets$$, $$Climate think tank$$, NULL, 2023, 2023, $$Lead Author$$, $$Wrote a briefing pack for negotiators from least developed countries on Article 6 carbon markets: how credits are authorised, corresponding adjustments, and safeguards for forest projects.$$, $$Pack used in two negotiator trainings before the climate summit.$$, $$[{"url":"https://picsum.photos/seed/demo-jonas-weber-lindqvist-briefing-pack-on-article-6-carbon-market-1/900/600","caption":"Negotiator training"}]$$::jsonb, $$[]$$::jsonb, NULL, 3);
INSERT INTO audio_testimonials (id, profile_id, work_history_entry_id, portfolio_item_id, reference_name, reference_org, reference_title, relationship, referee_email, referee_org_id, period_start, period_end, context, audio_path, transcript, transcript_source, transcript_confirmed_at, duration_seconds, source, submission_token, status, precheck_status, review_flags, opened_at, confirmed_at, details_accepted_at, consent_at, submitted_at, published_at, withdraw_token, created_at) VALUES ('02275800-b31e-51e4-baab-8df169373b3c', '19e6abe5-7d45-5fc7-bf74-b6c9b5d77180', $$25e1c1c3-37ef-4b58-bd81-b21a4727e7f1$$, NULL, $$Dr. Katrin Böhm$$, $$Stockholm Environment Institute$$, $$Senior Research Fellow$$, $$supervisor$$, $$katrin.bohm@sei.org$$, (SELECT id FROM organizations WHERE name = $$Stockholm Environment Institute$$), 2014, 2020, $$Climate policy at a German environmental NGO$$, $$demo/testimonial-6.m4a$$, $$[Demo testimonial: fictional referee, synthetic audio] I supervised Jonas at a German environmental NGO before I joined SEI. He wrote our climate policy briefs and ran advocacy campaigns that reached ministers. He knows the negotiations well and explains them clearly. I would work with him again on climate policy and advocacy.$$, $$auto$$, '2026-05-26T15:44:01.103Z'::timestamptz, 110, $$reference_direct$$, NULL, 'published', 'passed', '[]'::jsonb, '2026-05-24T15:44:01.103Z'::timestamptz, '2026-05-26T15:29:37.103Z'::timestamptz, '2026-05-26T15:36:49.103Z'::timestamptz, '2026-05-26T15:44:01.103Z'::timestamptz, '2026-05-26T15:44:01.103Z'::timestamptz, '2026-05-27T15:44:01.103Z'::timestamptz, $$05db755f3c35867389e7476c729fd8a9$$, '2026-05-23T15:44:01.103Z'::timestamptz);
