-- Oksana Melnyk-Hrytsenko
INSERT INTO portfolio_items (id, profile_id, project_name, organization, organization_id, start_year, end_year, role, description, results, images, links, video_url, sort_order) VALUES
  ('05b49ad3-d673-44cb-96a4-98ab1bf00e39', '59577cf7-481a-572b-9f52-81576e58150d', $$Reconstruction Project Tracking System$$, $$Development partner consortium$$, NULL, 2023, 2024, $$Digital Governance Advisor$$, $$Advised on a digital system tracking reconstruction projects from damage assessment to contract completion.$$, $$System covers thousands of reconstruction projects with public dashboards.$$, $$[{"url":"https://picsum.photos/seed/demo-oksana-melnyk-hrytsenko-portfolio-1/600/400","caption":null},{"url":"https://picsum.photos/seed/demo-oksana-melnyk-hrytsenko-portfolio-1-img1/900/600","caption":"Municipal training in Chernihiv"}]$$::jsonb, $$[]$$::jsonb, NULL, 1),
  ('ce2a3729-1178-4fb4-be8d-1372ac1d4cb7', '59577cf7-481a-572b-9f52-81576e58150d', $$Municipal E-Services Roll-Out$$, $$E-government programme (Kyiv)$$, NULL, 2017, 2020, $$Project Manager$$, $$Managed roll-out of online administrative services in 60 municipalities with change management.$$, $$Online service uptake reached 45% of eligible transactions.$$, $$[{"url":"https://picsum.photos/seed/demo-oksana-melnyk-hrytsenko-portfolio-2/600/400","caption":null},{"url":"https://picsum.photos/seed/demo-oksana-melnyk-hrytsenko-portfolio-2-img1/900/600","caption":"Administrative service centre"}]$$::jsonb, $$[]$$::jsonb, NULL, 2),
  ('339abb4f-01f2-551d-bd9a-51ad6ed1f5a5', '59577cf7-481a-572b-9f52-81576e58150d', $$Housing Compensation Process Review$$, $$UNDP$$, (SELECT id FROM organizations WHERE name = $$UNDP$$), 2024, 2025, $$Recovery Specialist$$, $$Reviewed the process for compensating households whose homes were destroyed or damaged, from application to payment, and recommended simplifications and municipal roles.$$, $$Processing steps cut from 14 to 8; municipalities given a clear role in damage verification.$$, $$[{"url":"https://picsum.photos/seed/demo-oksana-melnyk-hrytsenko-housing-compensation-process-review-1/900/600","caption":"Process mapping with municipal staff"}]$$::jsonb, $$[]$$::jsonb, NULL, 3);
INSERT INTO audio_testimonials (id, profile_id, work_history_entry_id, portfolio_item_id, reference_name, reference_org, reference_title, relationship, referee_email, referee_org_id, period_start, period_end, context, audio_path, transcript, transcript_source, transcript_confirmed_at, duration_seconds, source, submission_token, status, precheck_status, review_flags, opened_at, confirmed_at, details_accepted_at, consent_at, submitted_at, published_at, withdraw_token, created_at) VALUES ('b6016879-660c-50cf-907e-2c8f68d70f8a', '59577cf7-481a-572b-9f52-81576e58150d', $$2f461ce8-0e4c-45cf-8c02-a54bdfb7b8af$$, NULL, $$Iryna Kovalenko$$, $$UNDP$$, $$Governance Specialist$$, $$supervisor$$, $$iryna.kovalenko@undp.org$$, (SELECT id FROM organizations WHERE name = $$UNDP$$), 2011, 2022, $$Municipal e-services at an e-government programme in Kyiv$$, $$demo/testimonial-1.m4a$$, $$[Demo testimonial: fictional referee, synthetic audio] I worked with Oksana for eleven years at an e-government programme in Kyiv, as her manager, before I joined UNDP. She rolled out municipal e-services across dozens of cities and handled the change management with great skill. Since 2022 she has applied the same skills to recovery. I would work with her again.$$, $$auto$$, '2026-07-15T15:44:01.103Z'::timestamptz, 48, $$reference_direct$$, NULL, 'published', 'passed', '[]'::jsonb, '2026-07-13T15:44:01.103Z'::timestamptz, '2026-07-15T15:29:37.103Z'::timestamptz, '2026-07-15T15:36:49.103Z'::timestamptz, '2026-07-15T15:44:01.103Z'::timestamptz, '2026-07-15T15:44:01.103Z'::timestamptz, '2026-07-16T15:44:01.103Z'::timestamptz, $$89e85ef188e7c0ba55bd76b73dbaaa7c$$, '2026-07-12T15:44:01.103Z'::timestamptz);
