-- Losana Vakaloloma
INSERT INTO portfolio_items (id, profile_id, project_name, organization, organization_id, start_year, end_year, role, description, results, images, links, video_url, sort_order) VALUES
  ('092964b4-6d2b-4168-8b9f-aca1ce17ab4a', '87adf5b5-656f-52d7-8ea7-184af2fbb754', $$Community Relocation Planning, Vanua Levu$$, $$Government of Fiji$$, NULL, 2019, 2021, $$Lead Facilitator$$, $$Facilitated planning with three coastal villages considering relocation, with inclusion of persons with disabilities.$$, $$Plans endorsed by village councils and the national relocation taskforce.$$, $$[{"url":"https://picsum.photos/seed/demo-losana-vakaloloma-portfolio-1/600/400","caption":null},{"url":"https://picsum.photos/seed/demo-losana-vakaloloma-portfolio-1-img1/900/600","caption":"Village talanoa session"},{"url":"https://picsum.photos/seed/demo-losana-vakaloloma-portfolio-1-img2/900/600","caption":"Coastal erosion site"}]$$::jsonb, $$[]$$::jsonb, NULL, 1),
  ('bff693e8-8cbf-4e6a-b6ea-19983ea8ada0', '87adf5b5-656f-52d7-8ea7-184af2fbb754', $$Inclusive Disaster Preparedness Outreach$$, $$UNDP Pacific Office$$, (SELECT id FROM organizations WHERE name = $$UNDP$$), 2016, 2017, $$Outreach Coordinator$$, $$Ran public outreach on accessible early warnings and evacuation for persons with disabilities.$$, $$Accessible warning messages adopted by the national disaster office.$$, $$[{"url":"https://picsum.photos/seed/demo-losana-vakaloloma-portfolio-2/600/400","caption":null},{"url":"https://picsum.photos/seed/demo-losana-vakaloloma-portfolio-2-img1/900/600","caption":"Outreach session in Labasa"}]$$::jsonb, $$[]$$::jsonb, NULL, 2),
  ('61b55315-6ff7-518c-938f-873a81aa77d7', '87adf5b5-656f-52d7-8ea7-184af2fbb754', $$Inclusive Early Warning Messages for Outer Islands$$, $$UNDRR$$, (SELECT id FROM organizations WHERE name = $$UNDRR$$), 2023, 2023, $$Facilitator$$, $$Facilitated workshops with outer island communities, organisations of persons with disabilities and fishers to adapt cyclone early warning messages and evacuation plans.$$, $$Revised messages adopted by the national disaster office for the next cyclone season.$$, $$[{"url":"https://picsum.photos/seed/demo-losana-vakaloloma-inclusive-early-warning-messages-for-out-1/900/600","caption":"Community workshop on Kadavu"}]$$::jsonb, $$[]$$::jsonb, NULL, 3);
INSERT INTO audio_testimonials (id, profile_id, work_history_entry_id, portfolio_item_id, reference_name, reference_org, reference_title, relationship, referee_email, referee_org_id, period_start, period_end, context, audio_path, transcript, transcript_source, transcript_confirmed_at, duration_seconds, source, submission_token, status, precheck_status, review_flags, opened_at, confirmed_at, details_accepted_at, consent_at, submitted_at, published_at, withdraw_token, created_at) VALUES ('de1c4f31-21f7-5b09-bb2b-0ab76f098859', '87adf5b5-656f-52d7-8ea7-184af2fbb754', $$b4d54ea7-ee44-467d-9316-28f21af91ee6$$, NULL, $$Mereseini Tuilau$$, $$UNDP$$, $$Disability Inclusion Specialist$$, $$supervisor$$, $$mereseini.tuilau@undp.org$$, (SELECT id FROM organizations WHERE name = $$UNDP$$), 2008, 2015, $$Programmes at the Pacific disability forum$$, $$demo/testimonial-2.m4a$$, $$[Demo testimonial: fictional referee, synthetic audio] I was Losana's manager at the Pacific disability forum before joining UNDP. She is the best facilitator I know: she makes everyone in the room, with or without a disability, feel heard. Her work on inclusive disaster preparedness is still used. I would work with her again.$$, $$auto$$, '2026-06-05T15:44:01.103Z'::timestamptz, 62, $$reference_direct$$, NULL, 'published', 'passed', '[]'::jsonb, '2026-06-03T15:44:01.103Z'::timestamptz, '2026-06-05T15:29:37.103Z'::timestamptz, '2026-06-05T15:36:49.103Z'::timestamptz, '2026-06-05T15:44:01.103Z'::timestamptz, '2026-06-05T15:44:01.103Z'::timestamptz, '2026-06-06T15:44:01.103Z'::timestamptz, $$7cdb4c178a4d82e9af8b7abb0e4dbe0e$$, '2026-06-02T15:44:01.103Z'::timestamptz);
