-- Kila Nangui
INSERT INTO portfolio_items (id, profile_id, project_name, organization, organization_id, start_year, end_year, role, description, results, images, links, video_url, sort_order) VALUES
  ('6b621ce6-6cd8-413c-ad0c-fab33c477364', 'ec044c84-4d5d-5c10-b716-40bf0e0e04d2', $$Highlands Highway Road Safety Programme$$, $$Asian Development Bank$$, (SELECT id FROM organizations WHERE name = $$Asian Development Bank$$), 2018, 2021, $$Road Safety Coordinator$$, $$Led crash surveys and safety improvements along the Highlands Highway with community awareness.$$, $$Recorded crashes at treated black spots fell by 30%.$$, $$[{"url":"https://picsum.photos/seed/demo-kila-nangui-portfolio-1/600/400","caption":null},{"url":"https://picsum.photos/seed/demo-kila-nangui-portfolio-1-img1/900/600","caption":"Black spot treatment on the highway"}]$$::jsonb, $$[]$$::jsonb, NULL, 1),
  ('3fe405e4-4963-4e32-b69e-dfa82613638f', 'ec044c84-4d5d-5c10-b716-40bf0e0e04d2', $$Community Road Maintenance Groups$$, $$Australian Government (DFAT)$$, (SELECT id FROM organizations WHERE name = $$DFAT$$), 2014, 2017, $$Project Manager$$, $$Managed community maintenance contracts for rural roads used to bring coffee and produce to markets.$$, $$450 km maintained by 60 community groups.$$, $$[{"url":"https://picsum.photos/seed/demo-kila-nangui-portfolio-2/600/400","caption":null},{"url":"https://picsum.photos/seed/demo-kila-nangui-portfolio-2-img1/900/600","caption":"Community maintenance group"}]$$::jsonb, $$[]$$::jsonb, NULL, 2),
  ('97eebc10-af7a-51c5-8c9f-af84b76ee925', 'ec044c84-4d5d-5c10-b716-40bf0e0e04d2', $$Climate-Resilient Bridge Replacement Programme$$, $$World Bank$$, (SELECT id FROM organizations WHERE name = $$World Bank$$), 2021, 2023, $$Senior Project Engineer$$, $$Managed contracts to replace 18 single-lane bridges with climate-resilient designs on rural roads, including flood design standards, contractor supervision and safeguards monitoring.$$, $$18 bridges replaced; none closed during the 2023 floods.$$, $$[{"url":"https://picsum.photos/seed/demo-kila-nangui-climate-resilient-bridge-replacement-pro-1/900/600","caption":"Bridge site in Morobe"},{"url":"https://picsum.photos/seed/demo-kila-nangui-climate-resilient-bridge-replacement-pro-2/900/600","caption":"Contractor supervision"}]$$::jsonb, $$[]$$::jsonb, NULL, 3);
INSERT INTO audio_testimonials (id, profile_id, work_history_entry_id, portfolio_item_id, reference_name, reference_org, reference_title, relationship, referee_email, referee_org_id, period_start, period_end, context, audio_path, transcript, transcript_source, transcript_confirmed_at, duration_seconds, source, submission_token, status, precheck_status, review_flags, opened_at, confirmed_at, details_accepted_at, consent_at, submitted_at, published_at, withdraw_token, created_at) VALUES ('1d086580-fe1b-52ce-a9a4-fbace05171ce', 'ec044c84-4d5d-5c10-b716-40bf0e0e04d2', $$49c78fed-9498-483d-8d4f-28ebe762b6e8$$, NULL, $$Peter Hosea$$, $$Asian Development Bank$$, $$Senior Transport Specialist$$, $$client$$, $$phosea@adb.org$$, (SELECT id FROM organizations WHERE name = $$Asian Development Bank$$), 2018, 2021, $$Highlands Highway road safety programme$$, $$demo/testimonial-3.m4a$$, $$[Demo testimonial: fictional referee, synthetic audio] We worked with Kila on the Highlands Highway road safety programme. He managed contractors and communities along a difficult road with great patience and kept the works on schedule. He knows Papua New Guinea's roads better than anyone. I would work with him again on road and bridge programmes.$$, $$auto$$, '2026-07-05T15:44:01.103Z'::timestamptz, 75, $$reference_direct$$, NULL, 'published', 'passed', '[]'::jsonb, '2026-07-03T15:44:01.103Z'::timestamptz, '2026-07-05T15:29:37.103Z'::timestamptz, '2026-07-05T15:36:49.103Z'::timestamptz, '2026-07-05T15:44:01.103Z'::timestamptz, '2026-07-05T15:44:01.103Z'::timestamptz, '2026-07-06T15:44:01.103Z'::timestamptz, $$a8811d7b5f5ce852a205e12dd9683f7a$$, '2026-07-02T15:44:01.103Z'::timestamptz);
