-- Karim Fathy Soliman
INSERT INTO portfolio_items (id, profile_id, project_name, organization, organization_id, start_year, end_year, role, description, results, images, links, video_url, sort_order) VALUES
  ('81295592-26a0-416c-81e7-4533e9788e0b', '733b270c-913f-54b6-8b2c-6f4935db4528', $$Irrigation Modernization, Kafr El Sheikh$$, $$World Bank$$, (SELECT id FROM organizations WHERE name = $$World Bank$$), 2016, 2020, $$Project Manager$$, $$Managed modernization of 40,000 hectares of irrigation, including canal improvements and water user associations.$$, $$Water use efficiency improved and yields rose by 12%.$$, $$[{"url":"https://picsum.photos/seed/demo-karim-fathy-soliman-portfolio-1/600/400","caption":null},{"url":"https://picsum.photos/seed/demo-karim-fathy-soliman-portfolio-1-img1/900/600","caption":"Lined canal in the Delta"},{"url":"https://picsum.photos/seed/demo-karim-fathy-soliman-portfolio-1-img2/900/600","caption":"Water user association meeting"}]$$::jsonb, $$[]$$::jsonb, NULL, 1),
  ('f080323f-75fa-4220-b5a9-67a5a3e23659', '733b270c-913f-54b6-8b2c-6f4935db4528', $$Solar Irrigation Pumping Feasibility, Upper Egypt$$, $$IFAD$$, (SELECT id FROM organizations WHERE name = $$IFAD$$), 2022, 2023, $$Lead Engineer$$, $$Assessed feasibility and prepared financial models for solar-powered pumping for smallholders.$$, $$Pilot financed for 300 farms.$$, $$[{"url":"https://picsum.photos/seed/demo-karim-fathy-soliman-portfolio-2/600/400","caption":null},{"url":"https://picsum.photos/seed/demo-karim-fathy-soliman-portfolio-2-img1/900/600","caption":"Solar pump installation"}]$$::jsonb, $$[]$$::jsonb, NULL, 2),
  ('f05032f1-f86f-5f56-a827-8b6b0c04c5f0', '733b270c-913f-54b6-8b2c-6f4935db4528', $$Water User Organisation Training, Beheira$$, $$FAO$$, (SELECT id FROM organizations WHERE name = $$FAO$$), 2018, 2019, $$Irrigation Engineer$$, $$Trained water user organisations on canal maintenance, water scheduling and fee collection after the modernisation of mesqa canals, with farmer field days.$$, $$45 water user organisations trained; water delivery complaints down by half.$$, $$[{"url":"https://picsum.photos/seed/demo-karim-fathy-soliman-water-user-organisation-training-beheira-1/900/600","caption":"Farmer field day"},{"url":"https://picsum.photos/seed/demo-karim-fathy-soliman-water-user-organisation-training-beheira-2/900/600","caption":"Canal inspection"}]$$::jsonb, $$[]$$::jsonb, NULL, 3);
INSERT INTO audio_testimonials (id, profile_id, work_history_entry_id, portfolio_item_id, reference_name, reference_org, reference_title, relationship, referee_email, referee_org_id, period_start, period_end, context, audio_path, transcript, transcript_source, transcript_confirmed_at, duration_seconds, source, submission_token, status, precheck_status, review_flags, opened_at, confirmed_at, details_accepted_at, consent_at, submitted_at, published_at, withdraw_token, created_at) VALUES ('33895ed9-3f54-5739-9fd5-17017613ac53', '733b270c-913f-54b6-8b2c-6f4935db4528', $$e9931bdd-a790-41f8-90b3-eb09fa915bbe$$, NULL, $$Dr. Sameh Abdelrahman$$, $$FAO$$, $$Land and Water Officer$$, $$supervisor$$, $$sameh.abdelrahman@fao.org$$, (SELECT id FROM organizations WHERE name = $$FAO$$), 2001, 2015, $$Irrigation improvement at Egypt's water ministry$$, $$demo/testimonial-4.m4a$$, $$[Demo testimonial: fictional referee, synthetic audio] I supervised Karim at the irrigation improvement sector of Egypt's water ministry for many years, before I joined FAO. He is an excellent engineer who listens to farmers and designs systems they can maintain. His work in Kafr El Sheikh is a model. I would work with him again on irrigation and water projects.$$, $$auto$$, '2026-04-06T15:44:01.103Z'::timestamptz, 88, $$reference_direct$$, NULL, 'published', 'passed', '[]'::jsonb, '2026-04-04T15:44:01.103Z'::timestamptz, '2026-04-06T15:29:37.103Z'::timestamptz, '2026-04-06T15:36:49.103Z'::timestamptz, '2026-04-06T15:44:01.103Z'::timestamptz, '2026-04-06T15:44:01.103Z'::timestamptz, '2026-04-07T15:44:01.103Z'::timestamptz, $$504616afe3e4e67dfda6ccea4f7f90d6$$, '2026-04-03T15:44:01.103Z'::timestamptz);
