-- Leïla Benali Rossi
INSERT INTO portfolio_items (id, profile_id, project_name, organization, organization_id, start_year, end_year, role, description, results, images, links, video_url, sort_order) VALUES
  ('0660288d-2422-47b7-b742-ebf9c4d7daf3', '18d2862d-f78f-5b2c-a14f-c02199ffc530', $$Humanitarian Pledging Conferences$$, $$UN OCHA$$, (SELECT id FROM organizations WHERE name = $$OCHA$$), 2016, 2024, $$Interpreter$$, $$Interpreted Arabic, French and English at humanitarian pledging conferences and senior officials' meetings.$$, $$Interpreted at more than 30 high-level meetings.$$, $$[{"url":"https://picsum.photos/seed/demo-leila-benali-rossi-portfolio-1/600/400","caption":null},{"url":"https://picsum.photos/seed/demo-leila-benali-rossi-portfolio-1-img1/900/600","caption":"Interpreting booth at the Palais des Nations"}]$$::jsonb, $$[]$$::jsonb, NULL, 1),
  ('cc06f35c-b60a-4a06-9aa2-44ba433c9b81', '18d2862d-f78f-5b2c-a14f-c02199ffc530', $$Access Negotiations Support, Sahel$$, $$International humanitarian organization$$, NULL, 2020, 2021, $$Field Interpreter$$, $$Interpreted in confidential humanitarian access negotiations with local authorities and armed groups.$$, $$Supported agreements that reopened access to two districts.$$, $$[{"url":"https://picsum.photos/seed/demo-leila-benali-rossi-portfolio-2/600/400","caption":null},{"url":"https://picsum.photos/seed/demo-leila-benali-rossi-portfolio-2-img1/900/600","caption":"Field mission vehicle"}]$$::jsonb, $$[]$$::jsonb, NULL, 2),
  ('284381cc-c297-5b8e-a856-c3255fe4501e', '18d2862d-f78f-5b2c-a14f-c02199ffc530', $$Interpreter Training for Refugee Status Hearings$$, $$UNHCR$$, (SELECT id FROM organizations WHERE name = $$UNHCR$$), 2022, 2022, $$Trainer$$, $$Designed and delivered training for interpreters working in refugee status hearings: role and neutrality, trauma-aware practice and terminology.$$, $$40 interpreters trained in three countries.$$, $$[{"url":"https://picsum.photos/seed/demo-leila-benali-rossi-interpreter-training-for-refugee-status--1/900/600","caption":"Interpreter training"}]$$::jsonb, $$[]$$::jsonb, NULL, 3),
  ('4d46835a-8c1b-5f2c-ab14-2e99bfc24bce', '18d2862d-f78f-5b2c-a14f-c02199ffc530', $$Terminology Base for Humanitarian Negotiations$$, $$ICRC$$, (SELECT id FROM organizations WHERE name = $$ICRC$$), 2019, 2020, $$Terminologist$$, $$Built a shared Arabic–French–English terminology base for humanitarian negotiations, covering international humanitarian law and access terms.$$, $$Terminology base used by interpreters in three delegations.$$, $$[{"url":"https://picsum.photos/seed/demo-leila-benali-rossi-terminology-base-for-humanitarian-negoti-1/900/600","caption":"Terminology workshop"}]$$::jsonb, $$[]$$::jsonb, NULL, 4);
INSERT INTO audio_testimonials (id, profile_id, work_history_entry_id, portfolio_item_id, reference_name, reference_org, reference_title, relationship, referee_email, referee_org_id, period_start, period_end, context, audio_path, transcript, transcript_source, transcript_confirmed_at, duration_seconds, source, submission_token, status, precheck_status, review_flags, opened_at, confirmed_at, details_accepted_at, consent_at, submitted_at, published_at, withdraw_token, created_at) VALUES ('e47da174-6df0-5321-9d99-6a90fb1f6cc4', '18d2862d-f78f-5b2c-a14f-c02199ffc530', $$87ae88dc-9a99-4933-a1c4-f1d11563a0ca$$, NULL, $$Philippe Aubert$$, $$ICRC$$, $$Head of Language Services$$, $$supervisor$$, $$paubert@icrc.org$$, (SELECT id FROM organizations WHERE name = $$ICRC$$), 2004, 2008, $$Staff interpreting at an international humanitarian organization in Geneva$$, $$demo/testimonial-5.m4a$$, $$[Demo testimonial: fictional referee, synthetic audio] I supervised Leïla when she was a staff interpreter in Geneva, before I joined the ICRC's language services. She interpreted in sensitive negotiations with complete discretion and precision. She is one of the finest Arabic interpreters I know. I would work with her again on any humanitarian or diplomatic assignment.$$, $$auto$$, '2026-03-27T15:44:01.103Z'::timestamptz, 97, $$reference_direct$$, NULL, 'published', 'passed', '[]'::jsonb, '2026-03-25T15:44:01.103Z'::timestamptz, '2026-03-27T15:29:37.103Z'::timestamptz, '2026-03-27T15:36:49.103Z'::timestamptz, '2026-03-27T15:44:01.103Z'::timestamptz, '2026-03-27T15:44:01.103Z'::timestamptz, '2026-03-28T15:44:01.103Z'::timestamptz, $$239db33cb656707c90124db9dab62cc7$$, '2026-03-24T15:44:01.103Z'::timestamptz);
