INSERT INTO video_responses (id, profile_id, kind, question_id, video_url, video_path, transcript, duration_seconds) VALUES
  ('2c80613c-20f3-5abf-a3c7-349c2078a793', '18d2862d-f78f-5b2c-a14f-c02199ffc530', 'question', (SELECT id FROM interview_questions WHERE sort_order = 1 AND active ORDER BY id LIMIT 1), NULL, $$demo/qna-1.mp4$$, $$[Demo answer] I'm proudest of interpreting at humanitarian pledging conferences over eight years. My role is to make sure every delegation is heard. What changed is that smaller Arabic- and French-speaking delegations could speak with full confidence.$$, 20),
  ('b42dee78-b698-5271-b1c3-014c6a988ee0', '18d2862d-f78f-5b2c-a14f-c02199ffc530', 'question', (SELECT id FROM interview_questions WHERE sort_order = 2 AND active ORDER BY id LIMIT 1), NULL, $$demo/qna-2.mp4$$, $$[Demo answer] For access negotiations in the Sahel I prepared for a context I didn't know by building a glossary with field colleagues and listening to recordings of local terms before the meetings.$$, 20),
  ('4eb4b64b-841a-5e7f-b4c7-2283a1d3eb11', '18d2862d-f78f-5b2c-a14f-c02199ffc530', 'question', (SELECT id FROM interview_questions WHERE sort_order = 3 AND active ORDER BY id LIMIT 1), NULL, $$demo/qna-3.mp4$$, $$[Demo answer] When an interpreting team I led made an error in a sensitive meeting, I told the organisers immediately, corrected it on record, and changed our preparation process.$$, 20),
  ('cba8affe-0cc7-5943-873a-79f51f2c7a54', '18d2862d-f78f-5b2c-a14f-c02199ffc530', 'question', (SELECT id FROM interview_questions WHERE sort_order = 4 AND active ORDER BY id LIMIT 1), NULL, $$demo/qna-4.mp4$$, $$[Demo answer] Interpreting is working across cultures by definition. I always ask the people I interpret for about context, not just terms, because the meaning often lies in what is not said.$$, 20),
  ('368a9743-7bcb-5980-b4fb-a686b41d2375', '18d2862d-f78f-5b2c-a14f-c02199ffc530', 'question', (SELECT id FROM interview_questions WHERE sort_order = 5 AND active ORDER BY id LIMIT 1), NULL, $$demo/qna-5.mp4$$, $$[Demo answer] My specialism is simultaneous interpretation. It is not the right choice for small, sensitive conversations; then consecutive interpretation builds more trust.$$, 20);
