-- Selamawit Girma
INSERT INTO portfolio_items (id, profile_id, project_name, organization, organization_id, start_year, end_year, role, description, results, images, links, video_url, sort_order) VALUES
  ('5e23b100-b18c-4db8-9da2-7980c3e2c59f', '626f112f-2798-5e84-b6ce-469efa5c7850', $$Impact Evaluation of Nutrition-Sensitive Cash Transfers, Oromia$$, $$IFPRI$$, (SELECT id FROM organizations WHERE name = $$IFPRI$$), 2021, 2023, $$Evaluation Analyst$$, $$Contributed to a quasi-experimental impact evaluation of nutrition-sensitive cash transfers, designing the household survey module on child anthropometry and diets and running the statistical analysis.$$, $$Evaluation showed improved dietary diversity among children in treatment households and fed into the redesign of the safety net's nutrition component.$$, $$[{"url":"https://picsum.photos/seed/demo-selamawit-girma-portfolio-1/600/400","caption":null},{"url":"https://picsum.photos/seed/demo-selamawit-girma-portfolio-1-img1/900/600","caption":"Enumerator training on anthropometry"},{"url":"https://picsum.photos/seed/demo-selamawit-girma-portfolio-1-img2/900/600","caption":"Household survey in Oromia"}]$$::jsonb, $$[]$$::jsonb, NULL, 1),
  ('b1a89033-9b4b-4f9e-b16e-78fe4f2cf99c', '626f112f-2798-5e84-b6ce-469efa5c7850', $$Growth Monitoring and Counselling Review, Somali Region$$, $$Alive & Thrive$$, (SELECT id FROM organizations WHERE name = $$Alive & Thrive$$), 2018, 2019, $$Field Researcher$$, $$Reviewed how health extension workers deliver growth monitoring and infant feeding counselling in primary health care posts, combining observation and interviews with mothers.$$, $$Review led to a simplified counselling job aid used by health extension workers in the region.$$, $$[{"url":"https://picsum.photos/seed/demo-selamawit-girma-portfolio-2/600/400","caption":null},{"url":"https://picsum.photos/seed/demo-selamawit-girma-portfolio-2-img1/900/600","caption":"Observation at a health post"}]$$::jsonb, $$[]$$::jsonb, NULL, 2),
  ('c7b89fa1-a8c8-5b4b-b608-aed975a378c1', '626f112f-2798-5e84-b6ce-469efa5c7850', $$Maternal Health Service Readiness Survey, Oromia$$, $$IFPRI$$, (SELECT id FROM organizations WHERE name = $$IFPRI$$), 2023, 2024, $$Research Officer$$, $$Co-designed and analysed a facility survey of antenatal and delivery care readiness in 80 health centres and health posts, linking it to household data on use of maternal health services.$$, $$Findings used by the regional health bureau to target equipment and staffing in 20 health centres.$$, $$[{"url":"https://picsum.photos/seed/demo-selamawit-girma-maternal-health-service-readiness-survey-1/900/600","caption":"Health post visit"},{"url":"https://picsum.photos/seed/demo-selamawit-girma-maternal-health-service-readiness-survey-2/900/600","caption":"Survey data review"}]$$::jsonb, $$[]$$::jsonb, NULL, 3);
INSERT INTO audio_testimonials (id, profile_id, work_history_entry_id, portfolio_item_id, reference_name, reference_org, reference_title, relationship, referee_email, referee_org_id, period_start, period_end, context, audio_path, transcript, transcript_source, transcript_confirmed_at, duration_seconds, source, submission_token, status, precheck_status, review_flags, opened_at, confirmed_at, details_accepted_at, consent_at, submitted_at, published_at, withdraw_token, created_at) VALUES ('ba58b397-f0d8-5d64-a0d3-493e857775c0', '626f112f-2798-5e84-b6ce-469efa5c7850', $$c9f71c4f-f44c-43e7-b98d-bafd54a0a53e$$, NULL, $$Dr. Kalkidan Hassen$$, $$IFPRI$$, $$Senior Research Fellow$$, $$supervisor$$, $$k.hassen@ifpri.org$$, (SELECT id FROM organizations WHERE name = $$IFPRI$$), 2019, 2024, $$Research on cash transfers and maternal and child health in Ethiopia$$, $$demo/testimonial-1.m4a$$, $$[Demo testimonial: fictional referee, synthetic audio] Selamawit worked in my team at IFPRI for five years. She managed survey data for our evaluation of nutrition-sensitive cash transfers in Oromia, and her analysis was always careful and reproducible. She is quiet but very reliable, and field teams respect her. I would work with her again on evaluations and health surveys.$$, $$auto$$, '2026-08-04T15:44:01.103Z'::timestamptz, 48, $$reference_direct$$, NULL, 'published', 'passed', '[]'::jsonb, '2026-08-02T15:44:01.103Z'::timestamptz, '2026-08-04T15:29:37.103Z'::timestamptz, '2026-08-04T15:36:49.103Z'::timestamptz, '2026-08-04T15:44:01.103Z'::timestamptz, '2026-08-04T15:44:01.103Z'::timestamptz, '2026-08-05T15:44:01.103Z'::timestamptz, $$b4d71650424b39c7ddaa75e814729a98$$, '2026-08-01T15:44:01.103Z'::timestamptz);
