INSERT INTO portfolio_items (id, profile_id, project_name, organization, organization_id, start_year, end_year, role, description, results, images, links, video_url, sort_order) VALUES
  ('bccaeaf7-f752-4650-9a64-499e6dc4f92d', '8da9a180-74d3-571e-a8a4-4904c9ffc7da', $$Impact Evaluation of Nutrition-Sensitive Cash Transfers, Amhara$$, $$Concern Worldwide$$, (SELECT id FROM organizations WHERE name = $$Concern Worldwide$$), 2021, 2023, $$Evaluation Analyst$$, $$Contributed to a quasi-experimental impact evaluation of nutrition-sensitive cash transfers, designing the household survey module on child anthropometry and diets and running the statistical analysis.$$, $$Evaluation showed improved dietary diversity among children in treatment households and fed into the redesign of the safety net's nutrition component.$$, $$[{"url":"https://picsum.photos/seed/demo-yonas-alemu-portfolio-1/600/400","caption":null},{"url":"https://picsum.photos/seed/demo-yonas-alemu-portfolio-1-img1/900/600","caption":"Enumerator training on anthropometry"},{"url":"https://picsum.photos/seed/demo-yonas-alemu-portfolio-1-img2/900/600","caption":"Household survey in Amhara"}]$$::jsonb, $$[]$$::jsonb, NULL, 1),
  ('305b2e19-cb4d-443c-bfd9-09a8dfddeb39', '8da9a180-74d3-571e-a8a4-4904c9ffc7da', $$Growth Monitoring and Counselling Review, Somali Region$$, $$Ethiopian Public Health Institute$$, (SELECT id FROM organizations WHERE name = $$Ethiopian Public Health Institute$$), 2018, 2019, $$Field Researcher$$, $$Reviewed how health extension workers deliver growth monitoring and infant feeding counselling in primary health care posts, combining observation and interviews with mothers.$$, $$Review led to a simplified counselling job aid used by health extension workers in the region.$$, $$[{"url":"https://picsum.photos/seed/demo-yonas-alemu-portfolio-2/600/400","caption":null},{"url":"https://picsum.photos/seed/demo-yonas-alemu-portfolio-2-img1/900/600","caption":"Observation at a health post"}]$$::jsonb, $$[]$$::jsonb, NULL, 2),
  ('40e85735-16f6-5ad2-b7be-f3ab7ad488bb', '8da9a180-74d3-571e-a8a4-4904c9ffc7da', $$Community Health Worker Performance Review, Amhara$$, $$Concern Worldwide$$, (SELECT id FROM organizations WHERE name = $$Concern Worldwide$$), 2023, 2024, $$Research Officer$$, $$Reviewed the workload, supervision and supplies of health extension workers in four woredas, combining time-use observation with interviews and service records.$$, $$Supervision checklist revised and adopted by two zonal health departments.$$, $$[{"url":"https://picsum.photos/seed/demo-yonas-alemu-community-health-worker-performance-revi-1/900/600","caption":"Health extension worker interview"},{"url":"https://picsum.photos/seed/demo-yonas-alemu-community-health-worker-performance-revi-2/900/600","caption":"Service records review"}]$$::jsonb, $$[]$$::jsonb, NULL, 3);
INSERT INTO audio_testimonials (id, profile_id, work_history_entry_id, portfolio_item_id, reference_name, reference_org, reference_title, relationship, referee_email, referee_org_id, period_start, period_end, context, audio_path, transcript, transcript_source, transcript_confirmed_at, duration_seconds, source, submission_token, status, precheck_status, review_flags, opened_at, confirmed_at, details_accepted_at, consent_at, submitted_at, published_at, withdraw_token, created_at) VALUES ('56df3afb-4ff9-5002-be91-4f5ddc365013', '8da9a180-74d3-571e-a8a4-4904c9ffc7da', $$7c07cb91-3bb2-43ee-a651-265d6ac176c4$$, NULL, $$Meseret Tadesse$$, $$Concern Worldwide$$, $$Health and Nutrition Programme Manager$$, $$supervisor$$, $$meseret.tadesse@concern.net$$, (SELECT id FROM organizations WHERE name = $$Concern Worldwide$$), 2019, 2024, $$Nutrition research and evaluation in Amhara$$, $$demo/testimonial-2.m4a$$, $$[Demo testimonial: fictional referee, synthetic audio] Yonas worked with me at Concern for five years. He led the data work on our evaluation of nutrition-sensitive cash transfers in Amhara and trained our enumerators to a high standard. He is careful, honest about limitations and easy to work with. I would work with him again on nutrition and health evaluations.$$, $$auto$$, '2026-07-25T15:44:01.103Z'::timestamptz, 62, $$reference_direct$$, NULL, 'published', 'passed', '[]'::jsonb, '2026-07-23T15:44:01.103Z'::timestamptz, '2026-07-25T15:29:37.103Z'::timestamptz, '2026-07-25T15:36:49.103Z'::timestamptz, '2026-07-25T15:44:01.103Z'::timestamptz, '2026-07-25T15:44:01.103Z'::timestamptz, '2026-07-26T15:44:01.103Z'::timestamptz, $$818a244befe1b13037abb949becbb49f$$, '2026-07-22T15:44:01.103Z'::timestamptz);
