-- Hanna Tesfaye
INSERT INTO portfolio_items (id, profile_id, project_name, organization, organization_id, start_year, end_year, role, description, results, images, links, video_url, sort_order) VALUES
  ('163f424b-b120-4c7d-9398-76432ae035e8', 'c213a538-7504-5b5e-8a7f-da2b43d3eae7', $$Endline Impact Evaluation of a Nutrition-Sensitive Safety Net Pilot, Amhara$$, $$UNICEF Ethiopia$$, (SELECT id FROM organizations WHERE name = $$UNICEF$$), 2023, 2024, $$Evaluation Team Leader$$, $$Led a difference-in-differences impact evaluation of nutrition-sensitive cash transfers layered on the Productive Safety Net Programme in eight woredas. Designed the endline household survey (2,400 households), anthropometric protocols and enumerator training, and ran the statistical analysis.$$, $$Found a 6-point reduction in stunting among children under two in treatment woredas; the Ministry of Health used the findings to extend the nutrition-sensitive design to four more regions.$$, $$[{"url":"https://picsum.photos/seed/demo-hanna-tesfaye-portfolio-1/600/400","caption":null},{"url":"https://picsum.photos/seed/demo-hanna-tesfaye-portfolio-1-img1/900/600","caption":"Anthropometric measurement training for enumerators"},{"url":"https://picsum.photos/seed/demo-hanna-tesfaye-portfolio-1-img2/900/600","caption":"Validation workshop with the regional health bureau"}]$$::jsonb, $$[{"url":"https://example.org/amhara-psnp-nutrition-endline","label":"Evaluation summary"}]$$::jsonb, NULL, 1),
  ('498f9437-d40b-4db4-a2f3-91928bd215b8', 'c213a538-7504-5b5e-8a7f-da2b43d3eae7', $$SMART Nutrition Surveys in Pastoralist Woredas, Somali Region$$, $$Action Against Hunger$$, (SELECT id FROM organizations WHERE name = $$Action Against Hunger$$), 2021, 2022, $$Survey Lead$$, $$Designed and supervised SMART surveys in five pastoralist woredas, including sampling around seasonal mobility, mobile data collection and quality control.$$, $$Surveys established the first comparable wasting estimates for the woredas and triggered an expansion of outpatient therapeutic programme sites.$$, $$[{"url":"https://picsum.photos/seed/demo-hanna-tesfaye-portfolio-2/600/400","caption":null},{"url":"https://picsum.photos/seed/demo-hanna-tesfaye-portfolio-2-img1/900/600","caption":"Mobile data collection in a pastoralist kebele"}]$$::jsonb, $$[]$$::jsonb, NULL, 2),
  ('f1f21a6c-3010-44ea-bedb-080d17ca769f', 'c213a538-7504-5b5e-8a7f-da2b43d3eae7', $$Health Systems Readiness Assessment for Integrated Nutrition Services$$, $$Federal Ministry of Health, Ethiopia$$, NULL, 2019, 2020, $$Lead Researcher$$, $$Assessed staffing, therapeutic food supply chains, referral pathways and HMIS data quality in 60 primary health care facilities to inform integration of nutrition services into routine care.$$, $$Recommendations on supply forecasting and referral protocols were adopted in the national nutrition programme implementation manual.$$, $$[{"url":"https://picsum.photos/seed/demo-hanna-tesfaye-portfolio-3/600/400","caption":null},{"url":"https://picsum.photos/seed/demo-hanna-tesfaye-portfolio-3-img1/900/600","caption":"Facility assessment at a health centre"},{"url":"https://picsum.photos/seed/demo-hanna-tesfaye-portfolio-3-img2/900/600","caption":"Review of growth-monitoring records"}]$$::jsonb, $$[]$$::jsonb, NULL, 3),
  ('38b1a094-ab39-5343-b635-894e4cf23578', 'c213a538-7504-5b5e-8a7f-da2b43d3eae7', $$Mentoring Programme for Women Researchers$$, $$Ethiopian Public Health Institute$$, (SELECT id FROM organizations WHERE name = $$Ethiopian Public Health Institute$$), 2016, 2018, $$Programme Founder and Mentor$$, $$Set up and ran a mentoring programme pairing early-career women researchers with senior scientists, with writing retreats and support for first-author publications.$$, $$24 researchers mentored; 15 first-author papers published.$$, $$[{"url":"https://picsum.photos/seed/demo-hanna-tesfaye-mentoring-programme-for-women-researcher-1/900/600","caption":"Writing retreat in Bishoftu"}]$$::jsonb, $$[]$$::jsonb, NULL, 4);
INSERT INTO audio_testimonials (id, profile_id, work_history_entry_id, portfolio_item_id, reference_name, reference_org, reference_title, relationship, referee_email, referee_org_id, period_start, period_end, context, audio_path, transcript, transcript_source, transcript_confirmed_at, duration_seconds, source, submission_token, status, precheck_status, review_flags, opened_at, confirmed_at, details_accepted_at, consent_at, submitted_at, published_at, withdraw_token, created_at) VALUES ('541bb41d-38f4-5a56-a59e-afd67312d9ab', 'c213a538-7504-5b5e-8a7f-da2b43d3eae7', $$bbb0a501-eca9-48b9-a567-ef01fc8dba6f$$, NULL, $$Dr. Abebe Bekele$$, $$Ethiopian Public Health Institute$$, $$Director, Food Science and Nutrition Research$$, $$supervisor$$, $$abebe.bekele@ephi.gov.et$$, (SELECT id FROM organizations WHERE name = $$Ethiopian Public Health Institute$$), 2012, 2018, $$Nutrition research at EPHI$$, $$demo/testimonial-3.m4a$$, $$[Demo testimonial: fictional referee, synthetic audio] Hanna was a senior researcher in my directorate for six years. She led national nutrition surveys and several impact evaluations, and she built our mentoring programme for women researchers. She is one of the most rigorous and respected nutrition evaluators in Ethiopia. I would work with her again without hesitation.$$, $$auto$$, '2026-08-19T15:44:01.103Z'::timestamptz, 75, $$reference_direct$$, NULL, 'published', 'passed', '[]'::jsonb, '2026-08-17T15:44:01.103Z'::timestamptz, '2026-08-19T15:29:37.103Z'::timestamptz, '2026-08-19T15:36:49.103Z'::timestamptz, '2026-08-19T15:44:01.103Z'::timestamptz, '2026-08-19T15:44:01.103Z'::timestamptz, '2026-08-20T15:44:01.103Z'::timestamptz, $$8d2d1c3934c25136e3cb6312cb471833$$, '2026-08-16T15:44:01.103Z'::timestamptz);
