INSERT INTO audio_testimonials (id, profile_id, work_history_entry_id, portfolio_item_id, reference_name, reference_org, reference_title, relationship, referee_email, referee_org_id, period_start, period_end, context, audio_path, transcript, transcript_source, transcript_confirmed_at, duration_seconds, source, submission_token, status, precheck_status, review_flags, opened_at, confirmed_at, details_accepted_at, consent_at, submitted_at, published_at, withdraw_token, created_at) VALUES ('105d6579-74f8-5c70-b946-912a7669b4db', 'c213a538-7504-5b5e-8a7f-da2b43d3eae7', $$70e9b9bd-d161-4155-99af-acf228b77410$$, NULL, $$Liya Gebremedhin$$, $$UNICEF$$, $$Nutrition Specialist$$, $$supervisor$$, $$lgebremedhin@unicef.org$$, (SELECT id FROM organizations WHERE name = $$UNICEF$$), 2009, 2012, $$Nutrition programmes at UNICEF Ethiopia$$, $$demo/testimonial-4.m4a$$, $$[Demo testimonial: fictional referee, synthetic audio] I supervised Hanna as a nutrition officer at UNICEF Ethiopia. Even early in her career she was the person who checked every number. She supported our community-based management of acute malnutrition roll-out and trained health workers well. I have followed her career since with admiration.$$, $$auto$$, '2026-03-07T15:44:01.103Z'::timestamptz, 88, $$reference_direct$$, NULL, 'published', 'passed', '[]'::jsonb, '2026-03-05T15:44:01.103Z'::timestamptz, '2026-03-07T15:29:37.103Z'::timestamptz, '2026-03-07T15:36:49.103Z'::timestamptz, '2026-03-07T15:44:01.103Z'::timestamptz, '2026-03-07T15:44:01.103Z'::timestamptz, '2026-03-08T15:44:01.103Z'::timestamptz, $$fc51d1427541426b317d4a018a635025$$, '2026-03-04T15:44:01.103Z'::timestamptz);
