INSERT INTO video_responses (id, profile_id, kind, question_id, video_url, video_path, transcript, duration_seconds) VALUES
  ('184ce171-d86c-5678-96b5-0eb9109fa0aa', 'c213a538-7504-5b5e-8a7f-da2b43d3eae7', 'question', (SELECT id FROM interview_questions WHERE sort_order = 1 AND active ORDER BY id LIMIT 1), NULL, $$demo/qna-1.mp4$$, $$[Demo answer] I'm proudest of the endline evaluation of a nutrition-sensitive safety net pilot in Amhara. I led the design and analysis. What changed is that the government expanded the nutrition component nationally after we showed effects on child diets.$$, 20),
  ('9d99104e-c0f9-5711-956d-70d0780f43f4', 'c213a538-7504-5b5e-8a7f-da2b43d3eae7', 'question', (SELECT id FROM interview_questions WHERE sort_order = 2 AND active ORDER BY id LIMIT 1), NULL, $$demo/qna-2.mp4$$, $$[Demo answer] When I led SMART surveys in pastoralist areas of the Somali Region, the context was new to me. I worked closely with Somali-speaking supervisors and adjusted the survey calendar to herders' movements.$$, 20),
  ('f885ea6c-8480-5479-83f2-7dd817ed1184', 'c213a538-7504-5b5e-8a7f-da2b43d3eae7', 'question', (SELECT id FROM interview_questions WHERE sort_order = 3 AND active ORDER BY id LIMIT 1), NULL, $$demo/qna-3.mp4$$, $$[Demo answer] Our evaluation once found no effect on stunting. I presented it with the effects we did find on diets and services, and explained why stunting takes longer to move, so the result led to better design rather than cancellation.$$, 20),
  ('c0601748-01e4-5159-9ce4-32d1022e8c6a', 'c213a538-7504-5b5e-8a7f-da2b43d3eae7', 'question', (SELECT id FROM interview_questions WHERE sort_order = 4 AND active ORDER BY id LIMIT 1), NULL, $$demo/qna-4.mp4$$, $$[Demo answer] I work in Amharic, English and Tigrinya, and I always build teams with regional researchers. Local supervisors catch problems in the field that I would never see from Addis.$$, 20),
  ('0fc4909f-cd76-5378-9670-f459b4216fef', 'c213a538-7504-5b5e-8a7f-da2b43d3eae7', 'question', (SELECT id FROM interview_questions WHERE sort_order = 5 AND active ORDER BY id LIMIT 1), NULL, $$demo/qna-5.mp4$$, $$[Demo answer] I specialise in impact evaluation of nutrition programmes. It is not the right tool when a programme is too small or too new; then a well-designed monitoring system is more useful.$$, 20);
