  ('976f5ebe-ee3d-51db-a535-2b91c870bae4', 'c213a538-7504-5b5e-8a7f-da2b43d3eae7', 'employer', $$45c727b2-a1fc-4f1e-8b82-4fb134010945$$, $$Nutrition Evaluation Lead, Independent consultant, 2018–present$$, '3909a653', 'document_reviewed', 'document', $${"note":"Demo: contract with most recent client reviewed.","evidence":[{"kind":"file","mime_type":"application/pdf"}],"evidence_deleted_at":"2026-02-10T18:44:01.103Z"}$$::jsonb, 'admin', $$Demo Admin$$, '2026-02-10T19:44:01.103Z'::timestamptz),
  ('b1abd23b-fcb5-5032-8a8f-fe01b80c01e5', 'c213a538-7504-5b5e-8a7f-da2b43d3eae7', 'degree', $$55e2a8a5-8187-44f1-a67a-ca01d167933a$$, $$MSc Nutrition for Global Health, London School of Hygiene & Tropical Medicine, 2007–2008$$, '5dd502e9', 'document_reviewed', 'document', $${"note":"Demo: certificate checked for format, dates and consistency.","evidence":[{"kind":"file","mime_type":"application/pdf"}],"evidence_deleted_at":"2026-02-10T20:44:01.103Z"}$$::jsonb, 'admin', $$Demo Admin$$, '2026-02-10T21:44:01.103Z'::timestamptz),
