-- Abdiwali Hersi Warsame
INSERT INTO portfolio_items (id, profile_id, project_name, organization, organization_id, start_year, end_year, role, description, results, images, links, video_url, sort_order) VALUES
  ('aa3df0c8-cfd7-4c0d-afb9-fd24b3087e95', 'a392f260-9f5b-5543-a18c-b20b0ba251f0', $$Seasonal SMART Surveys, Somali Region of Ethiopia$$, $$Save the Children$$, (SELECT id FROM organizations WHERE name = $$Save the Children$$), 2022, 2024, $$Survey Manager$$, $$Led six rounds of SMART surveys in drought-affected woredas, including sampling design, anthropometric standardization tests and enumerator training in Somali.$$, $$Survey results informed the scale-up of outpatient therapeutic programme sites in three zones during the 2022–23 drought.$$, $$[{"url":"https://picsum.photos/seed/demo-abdiwali-hersi-warsame-portfolio-1/600/400","caption":null},{"url":"https://picsum.photos/seed/demo-abdiwali-hersi-warsame-portfolio-1-img1/900/600","caption":"Standardization test for MUAC measurement"},{"url":"https://picsum.photos/seed/demo-abdiwali-hersi-warsame-portfolio-1-img2/900/600","caption":"Enumerator training in Jigjiga"}]$$::jsonb, $$[{"url":"https://example.org/somali-region-smart-2023","label":"Survey summary"}]$$::jsonb, NULL, 1),
  ('740db825-d9cc-4cbc-bdb7-878b77f54524', 'a392f260-9f5b-5543-a18c-b20b0ba251f0', $$Nutrition Causal Analysis, Awdal and Togdheer$$, $$UNICEF Somalia$$, (SELECT id FROM organizations WHERE name = $$UNICEF$$), 2019, 2020, $$Field Research Lead$$, $$Combined household survey data and qualitative research with mothers and health workers to identify drivers of acute malnutrition in agro-pastoral communities.$$, $$Analysis led the nutrition cluster to add water trucking and infant feeding counselling to the regional response plan.$$, $$[{"url":"https://picsum.photos/seed/demo-abdiwali-hersi-warsame-portfolio-2/600/400","caption":null},{"url":"https://picsum.photos/seed/demo-abdiwali-hersi-warsame-portfolio-2-img1/900/600","caption":"Focus group with mothers in Awdal"}]$$::jsonb, $$[]$$::jsonb, NULL, 2),
  ('8105a27c-99e7-53a4-9592-e5554ab4e238', 'a392f260-9f5b-5543-a18c-b20b0ba251f0', $$Drought and Nutrition Early Warning Dashboard, Somali Region$$, $$FAO$$, (SELECT id FROM organizations WHERE name = $$FAO$$), 2024, 2025, $$Nutrition Surveillance Coordinator$$, $$Built a dashboard for the Somali Region of Ethiopia and Somaliland combining rainfall, livestock body condition and nutrition surveillance data (MUAC screening of children under five and SMART survey results on wasting and stunting) to give woreda health offices an early signal of drought impacts on child nutrition.$$, $$Dashboard used in two seasonal assessments; triggered early nutrition response in three woredas in 2025.$$, $$[{"url":"https://picsum.photos/seed/demo-abdiwali-hersi-warsame-drought-and-nutrition-early-warning-dash-1/900/600","caption":"Dashboard training for district officers"}]$$::jsonb, $$[]$$::jsonb, NULL, 3);
INSERT INTO audio_testimonials (id, profile_id, work_history_entry_id, portfolio_item_id, reference_name, reference_org, reference_title, relationship, referee_email, referee_org_id, period_start, period_end, context, audio_path, transcript, transcript_source, transcript_confirmed_at, duration_seconds, source, submission_token, status, precheck_status, review_flags, opened_at, confirmed_at, details_accepted_at, consent_at, submitted_at, published_at, withdraw_token, created_at) VALUES ('6064928c-b6cb-58eb-a588-a76abf1e3c01', 'a392f260-9f5b-5543-a18c-b20b0ba251f0', $$e30e954b-e6e7-441c-8a4f-423bab299702$$, NULL, $$Fadumo Ismail$$, $$Save the Children$$, $$Health and Nutrition Advisor$$, $$supervisor$$, $$fadumo.ismail@savethechildren.org$$, (SELECT id FROM organizations WHERE name = $$Save the Children$$), 2020, 2025, $$Nutrition surveillance in Somalia and the Somali Region of Ethiopia$$, $$demo/testimonial-5.m4a$$, $$[Demo testimonial: fictional referee, synthetic audio] Abdiwali coordinated our nutrition surveillance for five years. His SMART surveys were consistently high quality, even in insecure areas, and he trained a whole generation of Somali survey supervisors. He is calm, principled and respected by communities and authorities. I would work with him again on any nutrition survey.$$, $$auto$$, '2026-08-09T15:44:01.103Z'::timestamptz, 97, $$reference_direct$$, NULL, 'published', 'passed', '[]'::jsonb, '2026-08-07T15:44:01.103Z'::timestamptz, '2026-08-09T15:29:37.103Z'::timestamptz, '2026-08-09T15:36:49.103Z'::timestamptz, '2026-08-09T15:44:01.103Z'::timestamptz, '2026-08-09T15:44:01.103Z'::timestamptz, '2026-08-10T15:44:01.103Z'::timestamptz, $$8172e06370ec7d78b24eb0e310ca264f$$, '2026-08-06T15:44:01.103Z'::timestamptz);
