-- Dawit Kebede Abate
INSERT INTO portfolio_items (id, profile_id, project_name, organization, organization_id, start_year, end_year, role, description, results, images, links, video_url, sort_order) VALUES
  ('c069586f-5ece-4999-a3ba-7df1cda27ed5', '3e8dd2d0-9e2f-5843-bc4a-0cbfe901cec2', $$Bus Rapid Transit Corridor Feasibility Study, Addis Ababa$$, $$Addis Ababa City Administration$$, NULL, 2016, 2018, $$Transport Planning Lead$$, $$Led demand modelling, corridor design options and operating plans for the city's first BRT corridor.$$, $$Preferred option advanced to detailed design with development bank financing.$$, $$[{"url":"https://picsum.photos/seed/demo-dawit-kebede-abate-portfolio-1/600/400","caption":null},{"url":"https://picsum.photos/seed/demo-dawit-kebede-abate-portfolio-1-img1/900/600","caption":"Corridor survey on Ring Road"},{"url":"https://picsum.photos/seed/demo-dawit-kebede-abate-portfolio-1-img2/900/600","caption":"Stakeholder consultation with minibus operators"}]$$::jsonb, $$[]$$::jsonb, NULL, 1),
  ('87f3191b-5cdc-4cba-b3bd-c07206da0bed', '3e8dd2d0-9e2f-5843-bc4a-0cbfe901cec2', $$Municipal Road Safety Action Plans, Ethiopia$$, $$World Bank$$, (SELECT id FROM organizations WHERE name = $$World Bank$$), 2021, 2022, $$Road Safety Specialist$$, $$Analysed crash data and prepared road safety action plans for three secondary cities, including speed management and safer school zones.$$, $$Plans adopted by the three city councils; speed management pilots launched near twelve schools.$$, $$[{"url":"https://picsum.photos/seed/demo-dawit-kebede-abate-portfolio-2/600/400","caption":null},{"url":"https://picsum.photos/seed/demo-dawit-kebede-abate-portfolio-2-img1/900/600","caption":"Safer school zone pilot"}]$$::jsonb, $$[]$$::jsonb, NULL, 2),
  ('0a46e5bb-9d50-5025-b72a-22177e35c7d4', '3e8dd2d0-9e2f-5843-bc4a-0cbfe901cec2', $$Non-Motorised Transport Strategy, Addis Ababa$$, $$UN-Habitat$$, (SELECT id FROM organizations WHERE name = $$UN-Habitat$$), 2019, 2020, $$Senior Transport Planner$$, $$Led the city's non-motorised transport strategy: walking and cycling network plan, street design standards and a ten-year investment programme with cost-benefit analysis.$$, $$Strategy adopted; 40 kilometres of protected footpaths and cycle lanes built in the first phase.$$, $$[{"url":"https://picsum.photos/seed/demo-dawit-kebede-abate-non-motorised-transport-strategy-addis-a-1/900/600","caption":"Street design workshop"},{"url":"https://picsum.photos/seed/demo-dawit-kebede-abate-non-motorised-transport-strategy-addis-a-2/900/600","caption":"Pedestrian count"}]$$::jsonb, $$[]$$::jsonb, NULL, 3);
INSERT INTO audio_testimonials (id, profile_id, work_history_entry_id, portfolio_item_id, reference_name, reference_org, reference_title, relationship, referee_email, referee_org_id, period_start, period_end, context, audio_path, transcript, transcript_source, transcript_confirmed_at, duration_seconds, source, submission_token, status, precheck_status, review_flags, opened_at, confirmed_at, details_accepted_at, consent_at, submitted_at, published_at, withdraw_token, created_at) VALUES ('cf3c8d12-43bc-5bbf-871a-a23baea0fa47', '3e8dd2d0-9e2f-5843-bc4a-0cbfe901cec2', $$04787d84-6e47-4360-83fb-082d7fe04e9f$$, NULL, $$Benedict Asante$$, $$World Bank$$, $$Lead Transport Specialist$$, $$supervisor$$, $$basante@worldbank.org$$, (SELECT id FROM organizations WHERE name = $$World Bank$$), 2019, 2024, $$Urban transport and road safety operations in Ethiopia$$, $$demo/testimonial-6.m4a$$, $$[Demo testimonial: fictional referee, synthetic audio] Dawit worked with me for five years on urban transport in Ethiopia. He knows Addis Ababa's streets and institutions better than anyone, and his road safety action plans were adopted by several cities. He is a strong engineer and a patient negotiator. I would work with him again on transport projects.$$, $$auto$$, '2026-06-15T15:44:01.103Z'::timestamptz, 110, $$reference_direct$$, NULL, 'published', 'passed', '[]'::jsonb, '2026-06-13T15:44:01.103Z'::timestamptz, '2026-06-15T15:29:37.103Z'::timestamptz, '2026-06-15T15:36:49.103Z'::timestamptz, '2026-06-15T15:44:01.103Z'::timestamptz, '2026-06-15T15:44:01.103Z'::timestamptz, '2026-06-16T15:44:01.103Z'::timestamptz, $$5462e9d491f3248ac64aedd7cac536c1$$, '2026-06-12T15:44:01.103Z'::timestamptz);
