-- Nusrat Jahan Chowdhury
INSERT INTO portfolio_items (id, profile_id, project_name, organization, organization_id, start_year, end_year, role, description, results, images, links, video_url, sort_order) VALUES
  ('44564e59-375e-4491-95e1-a6f72a5bbbbc', '7b955afd-03a8-54ca-b884-f580abebb5f1', $$Endline Evaluation of Nutrition-Sensitive Cash Transfers, Ethiopia$$, $$World Food Programme$$, (SELECT id FROM organizations WHERE name = $$World Food Programme$$), 2022, 2023, $$Evaluation Team Leader$$, $$Led a difference-in-differences endline impact evaluation of nutrition-sensitive cash transfers in Amhara and the Somali region, with a household survey of 2,000 households and anthropometric measurement of children under five.$$, $$Evaluation found reduced wasting during the lean season and informed WFP's decision to make the transfers seasonal.$$, $$[{"url":"https://picsum.photos/seed/demo-nusrat-jahan-chowdhury-portfolio-1/600/400","caption":null},{"url":"https://picsum.photos/seed/demo-nusrat-jahan-chowdhury-portfolio-1-img1/900/600","caption":"Enumerator training in Jigjiga"},{"url":"https://picsum.photos/seed/demo-nusrat-jahan-chowdhury-portfolio-1-img2/900/600","caption":"Endline results workshop in Addis Ababa"}]$$::jsonb, $$[{"url":"https://example.org/wfp-ethiopia-nsct-endline","label":"Evaluation summary"}]$$::jsonb, NULL, 1),
  ('ca96141c-7712-4145-9b73-c6d9c1f67d2e', '7b955afd-03a8-54ca-b884-f580abebb5f1', $$Randomized Evaluation of Infant Feeding Counselling, Bangladesh$$, $$icddr,b$$, (SELECT id FROM organizations WHERE name = $$icddr,b$$), 2015, 2018, $$Principal Investigator$$, $$Designed and led a cluster-randomized impact evaluation of counselling delivered by community health workers, including survey design and statistical analysis.$$, $$Counselling improved minimum dietary diversity by 12 percentage points; the model was adopted into the national nutrition services package.$$, $$[{"url":"https://picsum.photos/seed/demo-nusrat-jahan-chowdhury-portfolio-2/600/400","caption":null},{"url":"https://picsum.photos/seed/demo-nusrat-jahan-chowdhury-portfolio-2-img1/900/600","caption":"Community health worker counselling session"}]$$::jsonb, $$[]$$::jsonb, NULL, 2),
  ('1e35074c-b499-56c2-8f0c-8897fd872f32', '7b955afd-03a8-54ca-b884-f580abebb5f1', $$Maternal Depression Screening Pilot, Dhaka$$, $$icddr,b$$, (SELECT id FROM organizations WHERE name = $$icddr,b$$), 2017, 2019, $$Co-Investigator$$, $$Co-led a pilot of maternal depression screening and brief counselling by community health workers in urban slums, with a cost analysis.$$, $$Screening added to the city corporation's maternal health package in two zones.$$, $$[{"url":"https://picsum.photos/seed/demo-nusrat-jahan-chowdhury-maternal-depression-screening-pilot-dhak-1/900/600","caption":"Community health worker training"}]$$::jsonb, $$[]$$::jsonb, NULL, 3),
  ('332ceb73-0f95-5b24-8404-d8ae37fec31a', '7b955afd-03a8-54ca-b884-f580abebb5f1', $$Systematic Review of Maternal and Newborn Care Packages$$, $$BRAC$$, (SELECT id FROM organizations WHERE name = $$BRAC$$), 2009, 2010, $$Research Fellow$$, $$Contributed to a systematic review of community-based maternal and newborn care packages in South Asia, extracting data and assessing study quality.$$, $$Review informed BRAC's maternal and newborn programme design.$$, $$[{"url":"https://picsum.photos/seed/demo-nusrat-jahan-chowdhury-systematic-review-of-maternal-and-newbor-1/900/600","caption":"Review team meeting"}]$$::jsonb, $$[]$$::jsonb, NULL, 4);
INSERT INTO audio_testimonials (id, profile_id, work_history_entry_id, portfolio_item_id, reference_name, reference_org, reference_title, relationship, referee_email, referee_org_id, period_start, period_end, context, audio_path, transcript, transcript_source, transcript_confirmed_at, duration_seconds, source, submission_token, status, precheck_status, review_flags, opened_at, confirmed_at, details_accepted_at, consent_at, submitted_at, published_at, withdraw_token, created_at) VALUES ('9bc8f2b9-f839-5a65-aaa9-9de264a59887', '7b955afd-03a8-54ca-b884-f580abebb5f1', $$475f8ed3-5d4e-4b22-bc94-4a6308c1423d$$, NULL, $$Dr. Tahmeed Rahman$$, $$icddr,b$$, $$Senior Scientist, Nutrition and Clinical Services$$, $$supervisor$$, $$trahman@icddrb.org$$, (SELECT id FROM organizations WHERE name = $$icddr,b$$), 2011, 2020, $$Nutrition research at icddr,b$$, $$demo/testimonial-1.m4a$$, $$[Demo testimonial: fictional referee, synthetic audio] Nusrat was a scientist in my division for nine years. She led randomised evaluations of infant feeding counselling and published widely, and she supervised field teams with care. She is an excellent epidemiologist with real practical sense. I would work with her again on nutrition and maternal health research.$$, $$auto$$, '2026-07-20T15:44:01.103Z'::timestamptz, 48, $$reference_direct$$, NULL, 'published', 'passed', '[]'::jsonb, '2026-07-18T15:44:01.103Z'::timestamptz, '2026-07-20T15:29:37.103Z'::timestamptz, '2026-07-20T15:36:49.103Z'::timestamptz, '2026-07-20T15:44:01.103Z'::timestamptz, '2026-07-20T15:44:01.103Z'::timestamptz, '2026-07-21T15:44:01.103Z'::timestamptz, $$5af9029beb7337cf6af2d9fb087bfdf7$$, '2026-07-17T15:44:01.103Z'::timestamptz);
