INSERT INTO audio_testimonials (id, profile_id, work_history_entry_id, portfolio_item_id, reference_name, reference_org, reference_title, relationship, referee_email, referee_org_id, period_start, period_end, context, audio_path, transcript, transcript_source, transcript_confirmed_at, duration_seconds, source, submission_token, status, precheck_status, review_flags, opened_at, confirmed_at, details_accepted_at, consent_at, submitted_at, published_at, withdraw_token, created_at) VALUES ('173e9e10-99f0-54e1-a463-6c2be0b474bb', '7b955afd-03a8-54ca-b884-f580abebb5f1', $$0331ade4-e83b-4717-af62-cb45fce7a60b$$, NULL, $$Farhana Kabir$$, $$BRAC$$, $$Director, Research and Evaluation$$, $$supervisor$$, $$farhana.kabir@brac.net$$, (SELECT id FROM organizations WHERE name = $$BRAC$$), 2008, 2011, $$Research on maternal and newborn health at BRAC$$, $$demo/testimonial-2.m4a$$, $$[Demo testimonial: fictional referee, synthetic audio] I supervised Nusrat as a research fellow at BRAC. She was already meticulous and thoughtful, and her work on community maternal and newborn care was well ahead of her experience. I am not surprised she became a leading nutrition evaluator.$$, $$auto$$, '2026-02-05T15:44:01.103Z'::timestamptz, 62, $$reference_direct$$, NULL, 'published', 'passed', '[]'::jsonb, '2026-02-03T15:44:01.103Z'::timestamptz, '2026-02-05T15:29:37.103Z'::timestamptz, '2026-02-05T15:36:49.103Z'::timestamptz, '2026-02-05T15:44:01.103Z'::timestamptz, '2026-02-05T15:44:01.103Z'::timestamptz, '2026-02-06T15:44:01.103Z'::timestamptz, $$3a8f1a4c9edbcf6c46d9858b675d7898$$, '2026-02-02T15:44:01.103Z'::timestamptz);
