INSERT INTO video_responses (id, profile_id, kind, question_id, video_url, video_path, transcript, duration_seconds) VALUES
  ('92244b8c-a502-5f17-8c30-09d2ba3881ca', '7b955afd-03a8-54ca-b884-f580abebb5f1', 'question', (SELECT id FROM interview_questions WHERE sort_order = 1 AND active ORDER BY id LIMIT 1), NULL, $$demo/qna-1.mp4$$, $$[Demo answer] I'm proudest of the randomised evaluation of infant feeding counselling in Bangladesh. I co-led it. What changed is that the counselling model was scaled through the national nutrition services.$$, 20),
  ('cba2062a-da06-528b-a3e8-c26dd1012f8f', '7b955afd-03a8-54ca-b884-f580abebb5f1', 'question', (SELECT id FROM interview_questions WHERE sort_order = 2 AND active ORDER BY id LIMIT 1), NULL, $$demo/qna-2.mp4$$, $$[Demo answer] For the endline evaluation in Ethiopia I worked far from home. I partnered with Ethiopian researchers from the start and relied on them for context, language and relationships with regional authorities.$$, 20),
  ('1c8a5dbd-1578-5a19-bc6f-1f219381b06b', '7b955afd-03a8-54ca-b884-f580abebb5f1', 'question', (SELECT id FROM interview_questions WHERE sort_order = 3 AND active ORDER BY id LIMIT 1), NULL, $$demo/qna-3.mp4$$, $$[Demo answer] When our results showed smaller effects than the funder hoped, I presented them with the cost per child reached and the components that worked, so the conversation was about improving the model.$$, 20),
  ('9b3437b1-44e9-54d3-ac00-545ffae35336', '7b955afd-03a8-54ca-b884-f580abebb5f1', 'question', (SELECT id FROM interview_questions WHERE sort_order = 4 AND active ORDER BY id LIMIT 1), NULL, $$demo/qna-4.mp4$$, $$[Demo answer] I work in Bengali, English and Hindi, and across South Asia and East Africa. I always learn how the health system works locally before designing anything.$$, 20),
  ('fa4eb828-03e6-5380-823c-30a25b2f9864', '7b955afd-03a8-54ca-b884-f580abebb5f1', 'question', (SELECT id FROM interview_questions WHERE sort_order = 5 AND active ORDER BY id LIMIT 1), NULL, $$demo/qna-5.mp4$$, $$[Demo answer] I specialise in randomised evaluations. They are not the right tool when the intervention cannot be held back from a comparison group for ethical reasons; then strong quasi-experimental designs are better.$$, 20);
