  ('d45e618d-350c-5ebb-8aad-b8a78f5064a9', '7b955afd-03a8-54ca-b884-f580abebb5f1', 'degree', $$fced70da-9de3-4f40-83ec-135e2c2630ae$$, $$PhD International Health (Human Nutrition), Johns Hopkins Bloomberg School of Public Health, 2005–2010$$, '4c9251a2', 'document_reviewed', 'document', $${"note":"Demo: certificate checked for format, dates and consistency.","evidence":[{"kind":"file","mime_type":"application/pdf"}],"evidence_deleted_at":"2026-01-11T20:44:01.103Z"}$$::jsonb, 'admin', $$Demo Admin$$, '2026-01-11T21:44:01.103Z'::timestamptz),
