-- Andrés Castillo Zelaya
INSERT INTO portfolio_items (id, profile_id, project_name, organization, organization_id, start_year, end_year, role, description, results, images, links, video_url, sort_order) VALUES
  ('32e6fb02-5490-4708-84c3-e5cdab33a7c6', '4fab5dd8-5405-5186-9fee-858b5c0d927e', $$Health Sector Procurement Red-Flag Analysis, Honduras$$, $$Transparency International$$, (SELECT id FROM organizations WHERE name = $$Transparency International$$), 2022, 2023, $$Lead Data Analyst$$, $$Built red-flag indicators (single bidding, direct awards, contract amendments) from five years of health sector procurement data and linked suppliers to the company registry.$$, $$Analysis identified supplier networks behind 40% of direct awards and was cited by the supreme audit institution in two audits.$$, $$[{"url":"https://picsum.photos/seed/demo-andres-castillo-zelaya-portfolio-1/600/400","caption":null},{"url":"https://picsum.photos/seed/demo-andres-castillo-zelaya-portfolio-1-img1/900/600","caption":"Supplier network visualization"},{"url":"https://picsum.photos/seed/demo-andres-castillo-zelaya-portfolio-1-img2/900/600","caption":"Presentation to journalists"}]$$::jsonb, $$[{"url":"https://example.org/honduras-health-procurement","label":"Data story"}]$$::jsonb, NULL, 1),
  ('76f510dc-5f76-4609-8869-da9106abd2c7', '4fab5dd8-5405-5186-9fee-858b5c0d927e', $$Open Contracting Dashboard for Public Works$$, $$CoST Honduras$$, (SELECT id FROM organizations WHERE name = $$CoST – Infrastructure Transparency Initiative$$), 2020, 2021, $$Data Developer$$, $$Developed a public dashboard of public works contracts published in the Open Contracting Data Standard, including contract amendments and cost overruns.$$, $$Dashboard used by citizen monitors in eight municipalities.$$, $$[{"url":"https://picsum.photos/seed/demo-andres-castillo-zelaya-portfolio-2/600/400","caption":null},{"url":"https://picsum.photos/seed/demo-andres-castillo-zelaya-portfolio-2-img1/900/600","caption":"Public works dashboard"}]$$::jsonb, $$[]$$::jsonb, NULL, 2),
  ('e4a0b965-40ba-5383-9846-32310c4efea2', '4fab5dd8-5405-5186-9fee-858b5c0d927e', $$Public Works Cost Overrun Analysis, Honduras$$, $$CoST – Infrastructure Transparency Initiative$$, (SELECT id FROM organizations WHERE name = $$CoST – Infrastructure Transparency Initiative$$), 2024, 2024, $$Data Analyst$$, $$Analysed 1,200 public works contracts to measure cost and time overruns by contracting entity and contract type, and built charts for a multi-stakeholder group's public report.$$, $$Report led the road agency to publish contract amendments online.$$, $$[{"url":"https://picsum.photos/seed/demo-andres-castillo-zelaya-public-works-cost-overrun-analysis-hondu-1/900/600","caption":"Multi-stakeholder group meeting"},{"url":"https://picsum.photos/seed/demo-andres-castillo-zelaya-public-works-cost-overrun-analysis-hondu-2/900/600","caption":"Overrun charts"}]$$::jsonb, $$[]$$::jsonb, NULL, 3);
INSERT INTO audio_testimonials (id, profile_id, work_history_entry_id, portfolio_item_id, reference_name, reference_org, reference_title, relationship, referee_email, referee_org_id, period_start, period_end, context, audio_path, transcript, transcript_source, transcript_confirmed_at, duration_seconds, source, submission_token, status, precheck_status, review_flags, opened_at, confirmed_at, details_accepted_at, consent_at, submitted_at, published_at, withdraw_token, created_at) VALUES ('c74c5847-72ec-5f05-8da1-09a54f5ef6c3', '4fab5dd8-5405-5186-9fee-858b5c0d927e', $$89a6eba7-e227-445b-b243-d57cc7b6524f$$, NULL, $$Karla Mejía$$, $$Open Contracting Partnership$$, $$Lead, Latin America$$, $$supervisor$$, $$kmejia@open-contracting.org$$, (SELECT id FROM organizations WHERE name = $$Open Contracting Partnership$$), 2016, 2021, $$Procurement data at ONCAE, Honduras$$, $$demo/testimonial-3.m4a$$, $$[Demo testimonial: fictional referee, synthetic audio] I supervised Andrés at ONCAE before I joined the Open Contracting Partnership. He built the data pipelines behind HonduCompras' open data and developed our first red-flag indicators. He is precise, curious and committed to transparency. I would work with him again on procurement data analysis.$$, $$auto$$, '2026-07-30T15:44:01.103Z'::timestamptz, 75, $$reference_direct$$, NULL, 'published', 'passed', '[]'::jsonb, '2026-07-28T15:44:01.103Z'::timestamptz, '2026-07-30T15:29:37.103Z'::timestamptz, '2026-07-30T15:36:49.103Z'::timestamptz, '2026-07-30T15:44:01.103Z'::timestamptz, '2026-07-30T15:44:01.103Z'::timestamptz, '2026-07-31T15:44:01.103Z'::timestamptz, $$01de5511c8902d2125578f68da6325d1$$, '2026-07-27T15:44:01.103Z'::timestamptz);
