INSERT INTO portfolio_items (id, profile_id, project_name, organization, organization_id, start_year, end_year, role, description, results, images, links, video_url, sort_order) VALUES
  ('f842ab83-aed6-42ee-84d2-ff89087a3342', '3051b2c9-2952-59c0-9a51-fb5a46feff79', $$Procurement Complaints and Debarment Study, Pakistan$$, $$World Bank$$, (SELECT id FROM organizations WHERE name = $$World Bank$$), 2021, 2022, $$Lead Researcher$$, $$Analysed procurement complaints and debarment decisions across four provinces and recommended reforms to the complaints mechanism.$$, $$Two provinces revised their complaint-handling rules based on the study.$$, $$[{"url":"https://picsum.photos/seed/demo-saad-ahmed-malik-portfolio-1/600/400","caption":null},{"url":"https://picsum.photos/seed/demo-saad-ahmed-malik-portfolio-1-img1/900/600","caption":"Consultation with procurement officers"}]$$::jsonb, $$[]$$::jsonb, NULL, 1),
  ('6a7e4eea-00f8-41be-b505-1b80abcfcdad', '3051b2c9-2952-59c0-9a51-fb5a46feff79', $$Court Case Management Reform, Khyber Pakhtunkhwa$$, $$UNDP Pakistan$$, (SELECT id FROM organizations WHERE name = $$UNDP$$), 2019, 2021, $$Justice Reform Advisor$$, $$Supported automation of case management in district courts and monitored case backlog indicators.$$, $$Average case processing time in pilot districts fell by a fifth.$$, $$[{"url":"https://picsum.photos/seed/demo-saad-ahmed-malik-portfolio-2/600/400","caption":null},{"url":"https://picsum.photos/seed/demo-saad-ahmed-malik-portfolio-2-img1/900/600","caption":"Case management training for court staff"}]$$::jsonb, $$[]$$::jsonb, NULL, 2),
  ('b51b826b-6ee5-57e0-ac37-c025c0cb30a9', '3051b2c9-2952-59c0-9a51-fb5a46feff79', $$Court Case Backlog Study, Punjab$$, $$UNDP$$, (SELECT id FROM organizations WHERE name = $$UNDP$$), 2023, 2024, $$Governance Analyst$$, $$Analysed case data from district courts to identify where civil and criminal cases stall, interviewed judges and court staff, and proposed case management changes.$$, $$Pilot case management rules adopted in three districts; backlog fell by 12% in a year.$$, $$[{"url":"https://picsum.photos/seed/demo-saad-ahmed-malik-court-case-backlog-study-punjab-1/900/600","caption":"Court records review"},{"url":"https://picsum.photos/seed/demo-saad-ahmed-malik-court-case-backlog-study-punjab-2/900/600","caption":"Workshop with district judges"}]$$::jsonb, $$[]$$::jsonb, NULL, 3);
INSERT INTO audio_testimonials (id, profile_id, work_history_entry_id, portfolio_item_id, reference_name, reference_org, reference_title, relationship, referee_email, referee_org_id, period_start, period_end, context, audio_path, transcript, transcript_source, transcript_confirmed_at, duration_seconds, source, submission_token, status, precheck_status, review_flags, opened_at, confirmed_at, details_accepted_at, consent_at, submitted_at, published_at, withdraw_token, created_at) VALUES ('d447c0c1-d272-54df-a56c-85a48995d787', '3051b2c9-2952-59c0-9a51-fb5a46feff79', $$9b1bee2c-a013-437f-ba7a-6006aaae492a$$, NULL, $$Ayesha Qureshi$$, $$UNDP$$, $$Assistant Resident Representative, Governance$$, $$supervisor$$, $$ayesha.qureshi@undp.org$$, (SELECT id FROM organizations WHERE name = $$UNDP$$), 2019, 2025, $$Governance and justice reform in Pakistan$$, $$demo/testimonial-4.m4a$$, $$[Demo testimonial: fictional referee, synthetic audio] Saad has worked in my governance unit since 2019. He led our court case management reform in Khyber Pakhtunkhwa and our case backlog study in Punjab, and he is trusted by judges and officials alike. He combines legal knowledge with good data skills. I would work with him again on governance and justice reform.$$, $$auto$$, '2026-07-10T15:44:01.103Z'::timestamptz, 88, $$reference_direct$$, NULL, 'published', 'passed', '[]'::jsonb, '2026-07-08T15:44:01.103Z'::timestamptz, '2026-07-10T15:29:37.103Z'::timestamptz, '2026-07-10T15:36:49.103Z'::timestamptz, '2026-07-10T15:44:01.103Z'::timestamptz, '2026-07-10T15:44:01.103Z'::timestamptz, '2026-07-11T15:44:01.103Z'::timestamptz, $$ec1c033b35379d46017191e5a5f96fdf$$, '2026-07-07T15:44:01.103Z'::timestamptz);
